-- Dumping data for table `tickets`
--

LOCK TABLES `tickets` WRITE;
/*!40000 ALTER TABLE `tickets` DISABLE KEYS */;
INSERT INTO `tickets` VALUES (1,1,1,'413230','Atualização do módulo Pagar.me','O cliente relatou que os pedido feito em sua loja pelo o método de pagamento Boleto Bancário da Pagar.me, não estavam  sendo atualizado o status do pedido na loja, quando a Pagar.me o notificava de que o pagamento tinha sido pago. E por isso, os pedidos estavam sendo cancelado por falta de verificação.','Foi instalado a versão mais atual do módulo Pagar.me','Resolvido','Baixa',NULL,'2024-03-25 16:43:19','2024-04-02 17:14:49'),(2,1,1,'412808','Atualização de status de pagamento Mercado Pago','O pedido esta com o pagamento Aprovado nas Informações de Pagamento, no comentário histórico também apareceu a atualização que o pedido atualizou para processando, mas o status do pedido permanece como pendente.','Segue o ajuste na atualização do status do pedido após o processamento da notificação recebida pela  a Mercado Pago.','Resolvido','Baixa',NULL,'2024-03-26 11:42:27',NULL),(3,1,1,'413269','Atualização do módulo Pagar.me','O cliente relata que os pedidos estão sendo aprovados no lado da Pagar.me mas o site não esta mudando o status para a integração ocorrer.','Foi feito a atualização do módulo.','Resolvido','Baixa',NULL,'2024-03-26 12:17:45','2024-04-02 17:14:59'),(4,3,3,'413284','Instalar o módulo da Frenet ','Instalar o módulo da Frenet na loja','','Resolvido','Baixa',NULL,'2024-03-26 14:09:21','2024-04-02 17:15:15'),(5,1,4,'413293','Instalação do módulo GA4','O cliente solicitou a instalação do módulo GA4','Foi instalado a versão mais atualizada do módulo.\r\n\r\nRepositório: https://git2bis.com.br/bis2bis/m1/modulos/dev-tools/google/google-analytics/-/tree/1.1.0?ref_type=tags','Resolvido','Baixa',NULL,'2024-03-26 17:53:59','2024-04-02 17:15:28'),(6,4,5,'413292','Atualizar do módulo Pagar.me','O checkout da loja não está  finalizando o pedido e por isso o cliente solicitou a atualização do módulo da pagar.me.','Foi instalado a versão mais atual do módulo','Resolvido','Baixa',NULL,'2024-03-26 19:01:15',NULL),(7,5,6,'413307','Instalação do módulo GA4','O cliente  solicitou a instalação do módulo','Instalado a versão mais atual do módulo.\r\n\r\nRepo: https://git2bis.com.br/bis2bis/m1/modulos/dev-tools/google/google-analytics/-/tree/1.1.0?ref_type=tags','Resolvido','Baixa',NULL,'2024-03-27 18:18:34',NULL),(8,5,8,'413433','Instalação do módulo GA4','Por gentileza, poderiam instalar o módulo: Módulo GA4, mesmo instalado na loja Good Pufes','Instalado a versão mais atualo do módulo GA\r\n\r\nRepo: https://git2bis.com.br/bis2bis/m1/modulos/dev-tools/google/google-analytics/-/tree/1.1.0?ref_type=tags','Resolvido','Baixa',NULL,'2024-03-27 18:26:15','2024-04-02 17:14:39'),(9,1,9,'413034','Banner home não exibi em mobile','O cliente se queixa de que o banner da página home não está aparecendo no display Mobile.','No momento em que eu assumi o ticket, eu somente limpei os caches da loja, Redis e CDN, e o banner voltou a aparecer.','Resolvido','Baixa',NULL,'2024-03-22 18:51:21',NULL),(10,1,10,'413182','Atualização do módulo Pagar.me','O cliente relata que os pedidos pago via boleto Pagar.me não estão  sendo integrados na loja, e por isso alguns pedidos não estão sendo atualizados automática mente e precisam ser atualizados manualmente.','Foi atualizado o módulo para a versão mais atual.','Resolvido','Baixa',NULL,'2024-03-22 19:34:26',NULL),(11,1,11,'413007','Instalação do módulo Pagar.me','O cliente relata que os clientes fizeram pedido por boleto, o mesmo foi pago o valor mas não caiu para a loja.','Foi instalado a última versão do módulo Pagar.me','Resolvido','Baixa',NULL,'2024-03-21 19:42:00',NULL),(12,1,12,'412902','Integração de boletos aprovados junto a PagarMe','O cliente relata que os pedidos pagos via boleto Pagar.me não estão atualizando o status do pedido na loja.','Atualizado o módulo para última versão.','Resolvido','Baixa',NULL,'2024-03-27 19:49:08',NULL),(13,3,8,'413402','Instalação do módulo Pagar.me','Os pedidos com pagamento em boleto estão aparecendo como pagos na plataforma da pagar.me, porém não estão aparecendo como pagos na plataforma do Magento, gostaria que verificassem a comunicação entre a plataforma de pagamentos.','Foi atualizado o módulo de pagamento Pagar.me','Resolvido','Baixa',NULL,'2024-03-28 12:28:50','2024-04-02 17:14:32'),(14,4,14,'412922','Atualização do módulo Pagar.me','Mesmo após a atualização os pedidos ainda não estão atualizando o status de forma automática. ','Foi atualizado o módulo para a versão mais atual.','Resolvido','Média',NULL,'2024-04-01 11:07:09','2024-04-02 17:14:22'),(15,6,15,'413208','Instalação do módulo Pagar.me','Olá prezados,\r\nPor gentileza, poderiam verificar a demanda abaixo:\r\nOrçar a instalação e configuração do módulo da pagar.me na loja \r\n','','Resolvido','Baixa',NULL,'2024-04-01 17:09:25','2024-04-02 17:14:09'),(16,1,16,'413087','Fornecimento dos endpoints para atualização do estoque','Cria um exemplo de requisição usando o método stockInventoryUpdate e o catalogProductUpdate atualizando o estoque de um produto e envia o exemplo anexo nesse ticket. Coloque também uma evidencia mostrando que a atualização de estoque ocorreu corretamente.','Segue em anexo o XML dos endpoints catalogInventoryStockItemUpdate e catalogProductUpdate, que são responsáveis por atualizarem a quantidade dos produtos em estoque.','Resolvido','Baixa',NULL,'2024-04-01 19:53:08',NULL),(17,1,18,'412772','Instalação do módulo XML Facebook','Por gentileza, poderia realizar a instalação do módulo do Facebook XML API.','Foi atualizado o módulo do Facebook XML para última versão do momento.','Resolvido','Baixa',NULL,'2024-04-01 19:58:05',NULL),(18,4,17,'413579','Atualizar módulo GA4','Por gentileza, atualizar o módulo do GA4 na loja.\r\nLoja com a versão mais atualizada: https://www.livrariasfamiliacrista.com.br/','O módulo foi atualizado para a última versão mais atual do  momento.','Resolvido','Baixa',NULL,'2024-04-02 11:38:51',NULL),(19,4,13,'413439','Instalação do módulo E-rede','Por gentileza, instalar o módulo da Rede na loja.','Instalado o módulo e encaminhado para o time QA para validação.','Resolvido','Baixa',NULL,'2024-04-02 11:42:00','2024-04-16 19:51:05'),(20,5,8,'413604','Instalação do módulo Pag Hiper','Olá prezados, \r\nPor gentileza, poderiam instalar o módulo: PagHiper completo\r\nBoleto e Pix.','As modalidades de Pix e Boleto Bancário, estão na  branch:  dev-feature/pix_method-EV-3094','Resolvido','Baixa',NULL,'2024-04-02 11:50:28','2024-04-02 17:13:40'),(21,7,13,'413651','Instalação do módulo Restrição de Pagamento','Bom dia,\r\npor favor instalar o módulo abaixo na loja de HOMOLOGAÇÂO. \r\n\r\nRepo: https://git2bis.com.br/bis2bis/m2/modulos/payment-tools/payment-restrictions','Instalado o módulo na versão: dev-develop.','Resolvido','Baixa',NULL,'2024-04-02 14:44:01','2024-04-02 17:18:33'),(23,4,19,'413592','Atualização do módulo Cielo v3','Estamos mudando de maquineta para cielo na perfatta, e quero socilitar uma mudança de metodo de pagamento para cielo tbm (Perfatta)','Foi instalado a versão master do módulo.\r\nRepo: https://git2bis.com.br/bis2bis/bis2bis-modules/bitbucket-modules/cielo-v3 ','Resolvido','Baixa',NULL,'2024-04-02 19:22:11','2024-07-24 17:42:16'),(24,4,22,'413618','Instalação do módulo Jadlog v2','Boa tarde, tudo bem?\r\nPor gentileza, instalar o módulo da Jadlog V2  na loja. ','Foi instalado a última atualização do módulo(development).','Resolvido','Baixa',NULL,'2024-04-03 13:24:38','2024-04-03 16:40:19'),(25,3,23,'413646','Instalação do módulo Autenticação de 2 fatores','Bom dia, por gentileza instalar o módulo na loja.','','Resolvido','Baixa',NULL,'2024-04-03 16:42:30','2024-04-03 20:47:02'),(26,1,5,'412928','Instalação do módulo Pagar.me','Bom dia!\r\nPessoal, nosso site não esta pegando os retornos dos pagamentos via boleto do pagarme - conseguem verificar?','Foi atualizado o módulo com  a última versão atualizada do módulo.','Resolvido','Baixa',NULL,'2024-04-19 16:50:54',NULL),(28,1,25,'412936','Instalação do módulo Pagar.me','Bom dia!\r\nUm cliente efetuou o pagamento de um boleto, na pagar.me está ok, o boleto caiu. Porem em nosso site consta como pendente ainda, acredito que esteja com problema na integração.','Foi  feito a atualização do módulo.','Resolvido','Baixa',NULL,'2024-04-19 17:15:41',NULL),(29,1,26,'412619','Instalação do módulo Google Merchant','Olá time!\r\nPoderiam instalar o modulo do Google Merchant igual ao da cia pneus','Instalado  o módulo.','Resolvido','Baixa',NULL,'2024-04-18 17:25:35',NULL),(30,1,27,'412855','Exibição da home page ao salvar promoção',' Ao tentar criar uma promoção, dentro de ações aparece a home da loja, mesmo apertando f5 não atualiza nem desloga do painel','Boa tarde equipe!\r\nForam realizadas alguns testes no ambiente de produção e não foi possível reproduzir o mau comportamento relatado pelo cliente na configuração/atualização na regra de promoção do carrinho de compras, como mostra a evidência abaixo.\r\n\r\n \r\n\r\nNos testes realizados, foram testados os seguintes cenários:\r\n\r\nCriação de uma nova regra de promoção.\r\n- Edição da regra de promoção\r\n- Limpeza de cache Redis e CDN\r\n\r\nContudo, sugiro que monitore essa loja para ver se o mesmo comportamento volta acontecer.','Resolvido','Baixa',NULL,'2024-04-18 17:51:29',NULL),(31,2,28,'412696','Atualização do módulo Pagar.me','Bom dia equipe, tudo bem?\r\n\r\nPor gentileza, poderia realizar a atualização no módulo do método de pagamento Pagar-me.\r\n\r\nConforme esta sendo aplicado na loja https://www.astrodistribuidora.com/ atraves do ticket 412340.','Módulo já  instalado','Resolvido','Baixa',NULL,'2024-04-03 17:59:07',NULL),(32,3,29,'412668','Instalar módulo Bloqueio de Compras','Boa tarde, por gentileza, poderia instalar o módulo \'Bloqueio de Compras\' na loja','Feito','Resolvido','Baixa',NULL,'2024-04-03 20:38:22',NULL),(33,2,30,'412695','Instalação da funcionalidade Pix PagSeguro','Boa tarde equipe, tudo bem?\r\nPoderiam instalar p PIX do PagSeguro na loja?','Feito','Resolvido','Baixa',NULL,'2024-04-03 20:41:47','2024-04-04 10:59:45'),(34,3,31,'413785','Instalação do módulo Exportação via Shell','Boa tarde! \r\nPor gentileza instalar o módulo de exportação via shell na loja. ','','Resolvido','Baixa',NULL,'2024-04-04 17:21:05','2024-04-05 17:25:19'),(35,4,33,'413826','Atualização do módulo Pagar.me','O módulo foi atualizado mas  ainda não esta atualizando o status dos pedidos','','Resolvido','Baixa',NULL,'2024-04-05 11:25:30','2024-04-05 12:45:49'),(36,3,32,'413842','Atualização do método de Pagamento Pagar-me','Os pedidos pagos via boleto não estão sendo atualizados quando pago.','','Resolvido','Baixa',NULL,'2024-04-05 12:34:20','2024-04-05 17:25:00'),(37,3,34,'413511','Atualização do módulo Google Shopping API','Olá bom dia!\r\nPor gentileza atualizar o módulo do google shopping, para que tenha o atributo de validação de produto disponível:','Atualizado com a última versão do módulo.','Resolvido','Baixa',NULL,'2024-04-05 17:24:47','2024-04-09 14:15:29'),(38,1,24,'412870','Bandeira da Discover Club não está aparecendo no checkout','A bandeira do cartão Discover Club não está aparecendo nas opções de pagamento no checkout','Foi alocado o arquivo de imagem da bandeira do cartão na  pasta de imagens','Resolvido','Baixa',NULL,'2024-04-06 13:47:05',NULL),(44,4,35,'413962','Atualização do módulo Pagar.me','Boa tarde, time\r\nPor gentileza, atualizar o módulo do Pagar-me na loja. Os pedidos via boleto não estão atualizando o status de forma automática. ','','Resolvido','Baixa',NULL,'2024-04-09 11:46:36','2024-04-09 14:45:20'),(45,3,36,'413995','Atualizar do módulo Pagar.me','Bom dia,\r\npor gentileza atualizar o módulo na loja, não está  atualizando os status dos pedidos\r\n','','Resolvido','Baixa',NULL,'2024-04-09 14:20:03','2024-04-09 14:44:11'),(46,2,37,'414004','Atualizar  o módulo Pagar.me','Bom dia equipe, tudo bem?\r\n\r\nPor gentileza, poderiam atualizar o módulo do método de pagamento Pagar.me conforme foi realizado na loja Astro (412340).\r\n\r\nA dificuldade na loja é que os pedidos mesmo após o pagamento continuam com o status pendente.','Instalado o módulo mais atual','Resolvido','Baixa',NULL,'2024-04-10 19:57:59','2024-04-11 14:13:46'),(47,2,38,'414154','Instalação do módulo Pagar.me','Boa tarde equipe, tudo bem?\r\n\r\nPor gentileza, poderia instalar o método de pagamento Pagar-me na loja.','Instalado a última versão do módulo.','Resolvido','Baixa',NULL,'2024-04-11 14:18:51','2024-04-11 14:58:51'),(48,7,39,'414231','Instalação do módulo Itaú Shopline','Boa tarde!\r\n\r\nfavor instalar o módulo ITAÚ SHOPLINE, conforme loja em produção: https://www.eletronservice.com.br','O módulo instalado, foi removido da própria loja em produção.','Resolvido','Baixa',NULL,'2024-04-12 12:12:05','2024-04-12 16:58:46'),(49,7,39,'414233','Instalação do módulo Frenet','Boa tarde,\r\npor favor instalar o módulo da frenet na loja nova.\r\nFRENET = Base loja em produção Eletron Service - São Paulo','O módulo já se encontra instalado.','Resolvido','Baixa',NULL,'2024-04-12 17:38:48',NULL),(50,7,39,'414234','Instalação do módulo de Otimização de Loja','Boa tarde,\r\nPor favor instalar o módulo  Otimizar Loja com base na loja em produção Eletron Service - São Paulo','','Resolvido','Baixa',NULL,'2024-04-12 17:45:35','2024-04-12 21:05:49'),(51,9,40,'413038','Cadastro de nova conta, falha na validação da data de nascimento','Boa tarde, tudo bem?\r\n\r\nAo realizar um cadatro na loja pelo carrinho de compra o mesmo não é salvo e somente atualiza a página.\r\n\r\nObs: A validação da data de nascimento está falhando e, por conta disso, o form n é enviado pro back. Desabilitar o campo de data de nascimento resolve temporariamente, mas é necessário debugar e corrigir a validação do campo para reativa-lo.','O erro que estava acontecendo era por causa de uma regra de validação \'validate-dob\' que estava que brando o js. Como o esse mesmo campo já possui uma regra de validação(validade-date) que faz a mesma coisa, o jeito foi remover a regra validate-dob das regras do campos.','Resolvido','Baixa',NULL,'2024-04-12 20:41:42','2024-04-17 18:04:15'),(60,2,41,'414237','Atualização do método de pagamento Pagar.me','Bom dia equipe, tudo bem?\r\n\r\nPor gentileza, poderia realizar a atualização no módulo do método de pagamento Pagar-me.','Atualizado como a última versão do módulo.','Resolvido','Baixa',NULL,'2024-04-17 18:09:15',NULL),(61,3,42,'414313','Orçamento de instalação da modalidade Pix do Mercado Pago','Bom dia,\r\npor gentileza orçar o módulo do mercado pago para PIX','','Resolvido','Baixa',NULL,'2024-04-17 19:12:49','2024-04-18 21:59:36'),(62,4,43,'414194','Falha na exibição dos produtos relacionados há categoria.','{\"ops\":[{\"insert\":\"Bom dia Equipe! Descrição da Falha: Dentro do cadastro do produto, na aba \\\"Categorias\\\" não esta sendo exibido as categorias cadastradas. Passos Tomados até o Momento: Já conferi o cadastro de categorias, e esta correto.\\n\"}]}','{\"ops\":[{\"insert\":\"Boa tarde equipe! \\n\\nSegue o ajuste da apresentação das categorias, no detalhes do produto, no painel administrativo. Será necessário executar uma instrução SQL no banco de dados da loja em produção, onde será corrigido a configuração da categoria raiz. \\n\\nA instrução SQL se encontra abaixo: \\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"UPDATE catalog_category_entity SET children_count=ABS(children_count) WHERE entity_id = 1277\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2024-04-17 19:24:54','2024-04-20 16:44:50'),(65,4,48,'414599','Limpeza dos dados do módulo Anymarket','Bom dia, tudo bem?\r\nPor gentileza, podem me auxiliar na exclusão do produto dentro do módulo da AnyMarket? Este produto foi excluído dentro do painel da Any e agora está causando conflito, não sendo possível desativá-lo daqui. ','Foi necessário executar um comando no banco de dados, como relatado no ticket e solicitado na task: https://bis2bis-jira.atlassian.net/browse/INFRA-3473','Resolvido','Baixa',NULL,'2024-04-22 12:48:05','2024-04-22 14:32:59'),(66,4,16,'414723','Instalação do móudlo Exportação de dados Via shell','Bom dia, time\r\nPor gentileza, instar o modo de exportação via shell na loja. ','','Resolvido','Baixa',NULL,'2024-04-22 14:35:15','2024-04-22 18:35:13'),(67,4,49,'414672','Atualização do módulo Mercado Pago - CC','Bom dia, time\r\nPor gentileza, atualizar o módulo do  Mercado Pago na loja.\r\nPreciso que o módulo seja igual ao da https://www.editoraculturacrista.com.br/ para ser possível personalizar as parcelas. ','','Resolvido','Baixa',NULL,'2024-04-22 18:41:03','2024-04-22 20:05:40'),(68,3,34,'414243','Histórico de atualização de produtos','Bom dia Equipe!\r\n\r\nLink: https://loja.sonhart.com.br/index.php/admin/catalog_product/edit/id/41049/key/0f46d9b9d2ecc88b11b1da4ae0513bf5/\r\n\r\nDescrição da Falha: ao clicar em \"history of changes\", está carregando mas não acessa as opções.\r\n\r\nComportamento padrão: mostrar o histórico das alterações do produto\r\n\r\nPassos Tomados até o Momento: testes e validação do erro\r\n\r\nAnexos: https://www.awesomescreenshot.com/video/26664715?key=ed6fcf193b38d17d1194aedf18308c75\r\n\r\nAtenciosamente,','','Resolvido','Baixa',NULL,'2024-04-22 21:05:13','2024-04-29 16:59:14'),(69,12,50,'412149','Instalação do módulo Login Social','Copiar o módulo daqui: https://git2bis.com.br/bis2bis/bis2bis-stores/oticasequilibrium/-/commit/5a2201dc6a583a45b96bb7c6c590b1ebb57245de','Instalação do módulo via pasta.','Resolvido','Baixa',NULL,'2024-04-23 19:40:29',NULL),(70,1,51,'414762','Instalação do módulo Pagar.me','Boa tarde Equipe!\r\n\r\nDescrição da Falha: Os pedidos tem seus pagamentos recebidos no painel do Pagar.me, mas não estão atualizando no painel administrativo.\r\n\r\nSegue o número do pedido: # 100044193\r\nPagamento efetuado no dia 16/04/24, via boleto bancário.','','Resolvido','Baixa',NULL,'2024-04-24 11:33:42','2024-04-24 13:08:57'),(71,5,52,'414915','Instalação do módulo GA4','Bruno,\r\nConsegui instalar em Staging, mas na hora de Mergear as branchs entraram em conflito. Poderia resolve-los por favor e subir? ','Finalizado a instalação do módulo GA4 e realizado o deploy para o ambiente de produção.','Resolvido','Baixa',NULL,'2024-04-24 19:31:16','2024-04-25 12:23:16'),(72,4,53,'414930','Instalação da modalidade Pix no módulo Mercado Pago','Bruno, boa tarde!\r\nAo tentar finalizar um pedido, estou recebendo o seguinte log de erro, pode me auxiliar?','','Resolvido','Baixa',NULL,'2024-04-25 13:02:06','2024-04-26 14:20:29'),(73,4,54,'415050','Atualização do módulo Pagar.me','Olá time, bom dia. \r\n\r\nPor gentileza, atualize o módulo do Pagar.me da loja, pois os pedidos via boleto não estão atualizando o status corretamente.','','Resolvido','Baixa',NULL,'2024-04-26 14:29:46','2024-04-26 17:55:17'),(74,2,55,'415060','Atualizar módulo Exportação de Planilhas via Shell','Bom dia equipe, tudo bem?\r\n\r\nPor gentileza, poderiam atualizar a loja para que seja possível exportar relatórios peloa modelo via Shell, conforme a loja https://www.casamedica.com.br/','','Resolvido','Baixa',NULL,'2024-04-26 17:55:08','2024-04-29 12:20:41'),(75,3,56,'414843','Atualizar módulo Pagar.me','Bom dia\r\npor gentileza atualizar o módulo na loja, as notificações não estão processando','','Resolvido','Baixa',NULL,'2024-04-26 18:03:09','2024-04-30 20:08:00'),(76,4,57,'415083','Instalação do módulo Pagar.me v5','Boa tarde, time\r\nPor gentileza, instalar o modulo do Pagar.me V5 na loja. ','O módulo não foi instalado, pois o cliente utiliza o checkout da Omny.','Resolvido','Baixa','SIM','2024-04-29 17:44:13','2024-05-01 16:24:46'),(77,4,58,'415059','Atualização do módulo Pagar.me','Bom dia, Time\r\nPor gentileza, atualizar o módulo do Pagar.me para versão mais recente. ','Foi instalado o módulo na versão 4','Resolvido','Baixa','SIM','2024-04-29 20:26:12','2024-05-06 11:14:55'),(78,1,62,'415139','Instalação do módulo GA4','O módulo foi instalado, mas ocorreu um conflito no deploy para a produção.','Conflito resolvido no repositório.','Resolvido','Baixa',NULL,'2024-04-30 16:48:51','2024-04-30 13:49:30'),(79,3,60,'415187','Atualização do módulo Pagar.me','Atualizar o módulo Pagar.me','Atualizado com a última versão do módulo na v4.','Resolvido','Baixa',NULL,'2024-05-02 11:54:31','2024-05-02 13:56:27'),(80,2,63,'415358','Instalação do módulo Autenticação de 2 fatores','Boa tarde equipe, tudo bem?\r\nPor gentileza, poderiam instalar o módulo de autenticação de dois fatores conforme a loja  https://www.editoramizuno.com.br/','','Resolvido','Baixa',NULL,'2024-05-03 16:49:23','2024-05-06 11:13:02'),(81,4,43,'414885','Exibição de imagem em miniatura na página de categoria','Alguns produtos estão exibindo a imagem em miniatura na categoria e na página inicial. E, ao abrir o produto, a imagem aparece pixelada. Porém, ao passar o mouse para dar zoom, a imagem é exibida com a nitidez correta.','O problema estava nas imagens que estavam com uma resolução baixa no diretório media/tmp/webp.\r\nApós resetar essa pasta, as imagens assumiram o tamanho original delas e o cenário se restabeleceu.','Resolvido','Baixa',NULL,'2024-05-03 18:56:06','2024-05-08 19:17:07'),(82,4,24,'415494','Instalação do módulo de exportação via Shell','Boa tarde, time!\r\nPor gentileza, instalar o módulo de exportação via Shell na loja. ','','Resolvido','Baixa',NULL,'2024-05-07 14:13:39','2024-05-07 18:08:02'),(83,4,64,'415544','Instalação do método de pagamento PagHiper','Bruno, bom dia. \r\nConversei com a lojista e ela deseja apenas a instalação do PIX - PagHiper.','https://git2bis.com.br/bis2bis/bis2bis-stores/sofa-casa/-/merge_requests/22','Resolvido','Baixa',NULL,'2024-05-07 18:09:27','2024-05-09 11:53:21'),(84,3,64,'415538','Instalação do módulo Paypal','Olá, bom dia por gentileza instalar o módulo na loja.','','Resolvido','Baixa',NULL,'2024-05-07 20:43:26','2024-05-08 11:18:39'),(85,2,32,'415554','Atualização do módulo via shell','Bom dia equipe, tudo bem?\r\nPor gentileza, poderia instalar o módulo via shell na loja conforme a loja https://www.casamedica.com.br/','','Resolvido','Baixa',NULL,'2024-05-09 11:30:57','2024-05-09 13:18:28'),(86,4,14,'415525','Instalação do módulo Exportação de Planilhas via Shell','Bom dia, time!\r\nPor gentileza, instalar o módulo de exportação via shell na loja. ','','Resolvido','Baixa',NULL,'2024-05-09 13:24:46','2024-05-09 14:36:09'),(87,1,65,'415553','Instalação do módulo de Ordenação de Produtos sem Estoque','Bruno, bom dia.!\r\nModulo que realiza essa configuração.\r\nLoja como referência: https://www.donacastanha.com.br/','Este módulo não tem repositório, e está nos documentos pessoais do notebook.\r\n\r\nDeploy: https://git2bis.com.br/bis2bis/bis2bis-stores/vegin/-/merge_requests/40\r\n\r\nCommit de referência: https://git2bis.com.br/bis2bis/bis2bis-stores/dona-castanha/-/commit/19a819689b2e46d57476478e384c6ce981d2ef95\r\n','Resolvido','Baixa',NULL,'2024-05-09 19:09:21','2024-05-10 11:41:22'),(88,4,66,'415686','Erro na exibição do parcelamento dos produtos','Bom dia Equipe!\r\nA exibição do parcelamento do pacote de produtos esta sendo exibido errado. ','Merge Request:\r\nhttps://git2bis.com.br/bis2bis/bis2bis-stores/divinah/-/merge_requests/10','Resolvido','Baixa',NULL,'2024-05-10 12:28:19','2024-05-10 20:50:38'),(89,4,67,'415717','Erro na exibição das imagens dos produtos na página de catálogo','Boa tarde, time\r\nAs imagens do site estavam sendo exibidas sem qualidade. Verifiquei que era o mesmo erro apresentado na loja ikebana que foi corrigido no ticket 414885. A dificuldade está relacionada ao módulo de WebP. Deixei o módulo desabilitado temporariamente para corrigir o erro. Podemos aplicar a mesma correção feita no ticket 414885?','Módulo instalado: https://git2bis.com.br/bis2bis/m1/modulos/dev-tools/webp\r\nVersão: develop','Resolvido','Baixa',NULL,'2024-05-10 22:03:48','2024-05-13 13:00:07'),(90,1,68,'415755','Instalação do módulo de Restrições de Pagamento','Bruno,\r\nO modulo que temos na Daniel é este: https://git2bis.com.br/bis2bis/m2/modulos/payment-tools/payment-restrictions','Versão do módulo instalado:\r\nhttps://git2bis.com.br/bis2bis/m2/modulos/payment-tools/payment-restrictions/-/tree/develop?ref_type=heads\r\n\r\nMerge Request:\r\nhttps://git2bis.com.br/bis2bis/m2/lojas/zoing-bisws/-/merge_requests/121\r\n\r\nApenas deploy realizado nesse dia.','Resolvido','Baixa',NULL,'2024-05-13 13:03:45','2024-05-14 11:19:48'),(91,7,69,'415864','Instalação do módulo de Marcas','Boa tarde,\r\nPoderiam por gentileza, realizar a implementação do módulo de Marcas? O mesmo segue instalado na loja http://alimentarequipamentos.bisws.com.br','Merge Request:\r\nhttps://git2bis.com.br/bis2bis/m2/lojas/way-suplementos-bisws/-/merge_requests/53\r\n\r\nRepositório do módulo:\r\nhttps://git2bis.com.br/bis2bis/m2/back/modulos/brands\r\n\r\nApenas deploy realizado nesse dia','Resolvido','Baixa',NULL,'2024-05-13 18:58:12','2024-05-14 11:33:21'),(92,2,70,'415870','Instalação do módulo Mercado Pago PIX','Boa tarde equipe, tudo bem?\r\nPoderiam instalar o módulo de pagamento Mercado Pago PIX na loja conforme a loja https://www.larshopping.com.br/','Merge Request:\r\nhttps://git2bis.com.br/bis2bis/bis2bis-stores/a-trolha/-/merge_requests/14','Resolvido','Baixa',NULL,'2024-05-14 11:37:56','2024-05-14 14:33:18'),(93,2,71,'415884','Instalação do módulo de Autenticação de Dois Fatores','Boa tarde, tudo bem?\r\nPoderiam instalar o módulo de autenticação de dois fatores conforme a loja https://www.tabacariadamata.com.br/','Merge Request:\r\nhttps://git2bis.com.br/bis2bis/bis2bis-stores/viso-store/-/merge_requests/36','Resolvido','Baixa',NULL,'2024-05-14 12:35:47','2024-05-14 14:33:51'),(94,3,72,'415762','Erro ao cadastrar tabela do Frete Gerenciável','Descrição da Falha: ao tentar cadastrar uma tabela, seja ela nova, ou que já esteja cadastrada, não finaliza o processo. Também tentie fazer manualmente, sem ser por planilha, e não salvou nenhuma informação.','Merge Request:\r\nhttps://git2bis.com.br/bis2bis/bis2bis-stores/bellenzier/-/merge_requests/106\r\n\r\nAguardando as alterações do @Arthur Barboza serem finalizadas para poder realizar o deploy em produção.','Resolvido','Baixa',NULL,'2024-05-14 19:23:19','2024-05-15 14:05:43'),(95,2,60,'415372','Pedido duplicado','Boa tarde!\r\nPor gentileza, poderiam verificar a causa da duplicação dos pedidos e gerar correção, está gerando necessidade de cancelar e estornar os valores gerados nos pedidos pagos com cartão de crédito:','O problema é causado pelo o módulo Recaptcha que esta sendo utilizado nos formulários do checkout.','Resolvido','Baixa',NULL,'2024-05-15 12:31:01','2024-05-15 18:05:34'),(96,3,73,'416009','Instalação do módulo da Clearsale','Bom dia!\r\npor gentileza instalar o módulo da Clearsale na loja','A instalação do módulo foi feita, porém, precisei reverter as alterações por que em produção a loja quebrou, por causa de uma atualização no modulo Redis.\r\n\r\nMerge Request:\r\nhttps://git2bis.com.br/bis2bis/bis2bis-stores/carolpapelaria/-/merge_requests/29','Resolvido','Baixa',NULL,'2024-05-15 17:51:18','2024-05-16 13:03:31'),(97,4,74,'416012','Instalação do módulo PagSeguro','Bom dia, time!\r\nPor gentileza, instale o módulo do PagSeguro na loja. Cartão de crédito e boleto. Atualmente, está configurado o PagSeguro transparente na loja.','Não foi necessário instalar o módulo pois o mesmo já estava instalado.','Resolvido','Baixa',NULL,'2024-05-16 13:34:23','2024-05-16 14:39:50'),(98,2,34,'415952','Endereço único no checkout','Boa tarde Equipe!\r\nO lojista solicitou no ticket #115315 para que a loja tenha endereço único, porém no checkout é possível adicionar um novo endereço.','Merge Request:\r\nhttps://git2bis.com.br/bis2bis/bis2bis-stores/sonhart/-/merge_requests/50\r\n\r\nTicket reaberto\r\n\r\nAguardando o alinha do time do suporte como o cliente','Fechado','Baixa',NULL,'2024-05-16 17:41:50','2024-05-21 13:10:44'),(99,4,75,'416080','Instalação do módulo: Atributo Nota Fiscal do Pedido','Bom dia, tudo bem?\r\n\r\nDentro do pedido, não possui o campo de nota fiscal. Podem instalar, por gentileza?\r\n\r\nLoja exemplo que possui o modulo; https://www.ofertamo.com.br/','Marge Request:\r\nhttps://git2bis.com.br/bis2bis/bis2bis-stores/loja-de-moveis-online/-/merge_requests/17\r\n\r\nRepositório do módulo:\r\nhttps://git2bis.com.br/bis2bis/m1/modulos/panel/order/invoice','Resolvido','Baixa',NULL,'2024-05-16 20:16:34','2024-05-17 13:22:28'),(100,3,76,'416088','Instalação do módulo GA4','Bom dia!\r\nPor gentileza instalar o módulo do GA4 na loja. ','Merge Request:\r\nhttps://git2bis.com.br/bis2bis/bis2bis-stores/romerodistribuidora/-/merge_requests/107','Resolvido','Baixa',NULL,'2024-05-17 14:39:15','2024-05-17 16:43:32'),(101,7,77,'416092','Instalação do módulo API','{\"ops\":[{\"insert\":\"Boa tarde, Por favor instalar o módulo API Bis2Bis. Ref. https://isaintimates.com.br/\\n\"}]}','{\"ops\":[{\"attributes\":{\"bold\":true},\"insert\":\"Módulo:\"},{\"insert\":\" \"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/m1/modulos/integrations/api \"},\"insert\":\"https://git2bis.com.br/bis2bis/m1/modulos/integrations/api \"},{\"attributes\":{\"bold\":true},\"insert\":\"Versão:\"},{\"insert\":\" development \\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Merge request:\"},{\"insert\":\" \"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/4x4racer/-/merge_requests/2\"},\"insert\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/4x4racer/-/merge_requests/2\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2024-05-17 17:52:26','2024-05-17 13:19:35'),(102,3,57,'416106','Instalação do módulo de exportação via Shell','Boa tarde!\r\npor gentileza instalar o módulo de exportação Shell','Merge Request:\r\nhttps://git2bis.com.br/bis2bis/bis2bis-stores/lemonpaper/-/merge_requests/25','Resolvido','Baixa',NULL,'2024-05-17 18:28:03','2024-05-17 20:36:14'),(103,2,78,'416187','Instalação do módulo de Entrega Intelipost','Bom dia equipe, tudo bem?\r\nPor gentileza, poderia instalar o módulo de entrega Intelipost conforme a loja https://www.shoptendtudo.com.br/','Merge Request:\r\nhttps://git2bis.com.br/bis2bis/bis2bis-stores/diasbike/-/merge_requests/49\r\n\r\nRepositório do módulo:\r\nhttps://git2bis.com.br/bis2bis/bis2bis-modules/bitbucket-modules/intelipost/-/tree/development?ref_type=heads','Resolvido','Baixa',NULL,'2024-05-20 12:38:58','2024-05-20 14:39:17'),(104,7,79,'416094','Instalação do módulo Lista de Desejo(Wishlist)','Boa tarde!\r\nInstalar o Módulo Wishlist\r\nLoja de Ref.:https://www.bananadaterrabrasil.com.br/','O módulo que está instalado na loja de referência(Banana da Terra Brasil) é um módulo nativo da plataforma Magento, e é a mesma que também está instalado nessa loja.\r\n\r\nMage_Wishlist\r\n\r\nO motivo da pausa, foi por que a loja que esta instalada no repositório é M1 e  no contrato do cliente a loja é M2. A infra esta ajustando esse equivoco, e assim que estiver ajustado, instalar os modulos','Fechado','Baixa',NULL,'2024-05-20 14:43:07','2024-05-20 20:17:53'),(105,7,79,'416095','Instalação do módulo Frete Faltante','Boa tarde!\r\nInstalar o Módulo Frete Faltante\r\nLink Ref.:https://www.bananadaterrabrasil.com.br/','O módulo instalado, foi extraído da loja Banana da Terra Brasil, e está alocando nos documentos do note.\r\n\r\nMerge requrest:\r\nhttps://git2bis.com.br/bis2bis/bis2bis-stores/maxxmoveis/-/merge_requests/1\r\n\r\nDeploy:\r\nhttps://git2bis.com.br/bis2bis/bis2bis-stores/maxxmoveis/-/commit/c594d88c90853c2a3d14afc7fe7c8ac26b785eaa\r\n\r\nO motivo da pausa, foi por que a loja que esta instalada no repositório é M1 e  no contrato do cliente a loja é M2. A infra esta ajustando esse equivoco, e assim que estiver ajustado, instalar os modulos','Fechado','Baixa',NULL,'2024-05-20 17:23:41','2024-05-20 20:17:31'),(106,2,18,'416279','Instalar o módulo Redes Sociais','Bruno,\r\npor gentileza instalar o módulo de redes sociais, para que seja possível inserir o whatsapp no rodapé da loja.\r\n\r\nLoja exemplo: https://www.donacastanha.com.br/','Merge Request:\r\nhttps://git2bis.com.br/bis2bis/bis2bis-stores/mult-comercial/-/merge_requests/31\r\n\r\nReabertura do ticket.\r\n\r\nMerge Request:\r\nhttps://git2bis.com.br/bis2bis/bis2bis-stores/mult-comercial/-/merge_requests/33\r\n\r\nhttps://git2bis.com.br/bis2bis/bis2bis-stores/mult-comercial/-/merge_requests/35','Resolvido','Baixa',NULL,'2024-05-21 11:01:43','2024-05-23 11:36:02'),(107,13,80,'416195','Instalação do módulo GA4','Olá prezados!\r\n\r\nPor gentileza, poderiam instalar o módulo: GA4 loja referência Good Pufes https://www.goodpufes.com.br/','Merge Request:\r\nhttps://git2bis.com.br/bis2bis/bis2bis-stores/cafe-odebrecht/-/merge_requests/6','Resolvido','Baixa',NULL,'2024-05-21 14:13:41','2024-05-23 11:36:31'),(108,7,72,'416245','Erro ao acessar tela no admin','Bom dia!\r\nNão é possivel acessar a página de clientes Clientes > Gerenciar Clientes dentro do painel administrativo da url produção.','Será necessário executar um comando SQL na base de dados onde deverá ser resetado a configuração do módulo base e ao atualizar a loja, essa configuração será executada, o atributo criado e a página voltará a funcionar.\r\n\r\nhttps://bis2bis-jira.atlassian.net/browse/INFRA-3646\r\n\r\nReabertura do ticket\r\nComo o atributo \'full_name\' estava recentemente configurado na loja, a base de dados ainda não possuía registro vinculados há esse atributo. Contudo foi necessário implementar um script PHP para o preenchimento desse atributo, após feito e executado em produção, a listagem dos clientes voltou a funcionar.','Resolvido','Baixa',NULL,'2024-05-21 17:10:28','2024-05-23 18:02:11'),(109,3,67,'416355','O botão de upload das imagens não aparece no cadastro do produto.','Bom dia Equipe!\r\n\r\nDescrição da Falha: o botão de upload das imagens sumiu do cadastro dos produtos\r\nComportamento padrão: exibir botão','O problema foi resolvido, instalando o módulo BIS2BIS/Uploader.\r