bis.com.br/bis2bis/bis2bis-stores/omk/-/commit/c6e4d0e0aa1c929b2d349558ffc36a85ae7fc89e\"},\"insert\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/omk/-/commit/c6e4d0e0aa1c929b2d349558ffc36a85ae7fc89e\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-01-17 13:36:49','2025-01-21 16:26:05'),(343,4,157,'429427','Alterar o nome do cliente na grid de pedidos','{\"ops\":[{\"insert\":\"Por gentileza, podem realizar o ajuste abaixo:\\n\\nNa sessão de pedidos, a coluna \\\"Cliente\\\" está exibindo o nome inserido no \\\"Endereço dos clientes\\\", o que está gerando confusão. Isso ocorre porque, ao acessar o pedido, o nome exibido no cadastro do cliente pode ser diferente do nome informado no endereço. O ajuste necessário é que, na coluna \\\"Cliente\\\", seja exibido o nome cadastrado do cliente, em vez do nome do endereço.\\n\"}]}','{\"ops\":[{\"insert\":\"Deploy: \"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/concordepr/-/commit/eb0d8bdf29bcabe78190179d99995a2e339aa9a9\"},\"insert\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/concordepr/-/commit/eb0d8bdf29bcabe78190179d99995a2e339aa9a9\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-01-20 08:32:02','2025-01-22 15:56:21'),(344,4,194,'429597','Instalação do módulo MFA','{\"ops\":[{\"insert\":\"Olá, boa tarde. Tudo bem?\\n\\nTime, por gentileza instalar o módulo de autenticação de dois fatores na loja.\\n\"}]}','{\"ops\":[{\"insert\":\"Deploy: \"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/alternativa-foto-produto/-/commit/151e925e16391a61baa587b6a576e2793e41d1cd\"},\"insert\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/alternativa-foto-produto/-/commit/151e925e16391a61baa587b6a576e2793e41d1cd\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-01-21 15:30:40','2025-01-21 15:48:27'),(345,4,102,'429569','Instalação do módulo Pagar.me v5','{\"ops\":[{\"insert\":\"Olá time!\\n\\nPor gentileza, instalar o módulo na loja.\\n\"}]}','{\"ops\":[{\"insert\":\"Deploy: \"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/kinghouse-bisws/-/commit/06ec4fdd78b464c444879265666543d58c206d69\"},\"insert\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/kinghouse-bisws/-/commit/06ec4fdd78b464c444879265666543d58c206d69\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-01-21 17:49:09','2025-01-22 09:40:19'),(346,13,170,'429534','Atualização do módulo LGPD','{\"ops\":[{\"insert\":\"Olá prezados!\\n\\nPor gentileza, poderiam atualizar o módulo LGPD na Armarinho Ambar? Usar como referência a \"},{\"attributes\":{\"bold\":true},\"insert\":\"Casa Médica\"},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"insert\":\"Deploy: \"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/armarinhoambar/-/commit/b49016dbf2d1c42037710f305f5723eef686c0c8\"},\"insert\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/armarinhoambar/-/commit/b49016dbf2d1c42037710f305f5723eef686c0c8\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-01-22 09:13:18','2025-01-23 11:43:33'),(347,3,11,'429405','Exibição de produtos sem estoque','{\"ops\":[{\"insert\":\"Olá Equipe, Boa tarde!\\n\\nDescrição do Problema: Na categoria \"},{\"attributes\":{\"link\":\"https://www.hsmerch.com/marcas/alkaline-trio.html\"},\"insert\":\"https://www.hsmerch.com/marcas/alkaline-trio.html\"},{\"insert\":\" está exibindo o filtro de Tamanho G, quando clico no filtro, aparecem dois produtos que não possuem o tamanho G em estoque. Mesmo indexando a loja, não corrige essa questão.\\n\\nAção Necessária: Verificar o erro que está apresentando produtos que não possuem na loja\\n\"}]}','{\"ops\":[{\"insert\":\"Bom dia equipe!\\n\\nO comportamento descrito como \\\"falha\\\" no carregamento dos produtos, na verdade é o comportamento nativo da plataforma, visto que, os filtros das categorias retornam os produtos que possuem o atributo selecionado e não verifica se a variação possuí ou não produtos no estoque.\\n\\nEsse comportamento de verificação da disponibilidade do produto em estoque, é passivo de orçamento pois entende-se que esse comportamento se trata de uma melhoria na loja. \\n\\nO @Eduardo Sanches está á par da situação.\\n\\nNo mais, fico á disposição.\\n\"}]}','Resolvido','Baixa',NULL,'2025-01-22 16:01:15','2025-01-27 11:15:12'),(348,4,18,'429659','Instalar a funcionalidade Gerenciar Status','{\"ops\":[{\"insert\":\"Olá, time.\\n\\nPor gentileza, podem incluir a aba de gerenciar status dentro da aba de pedidos no painel admin?\\n\"}]}','{\"ops\":[{\"insert\":\"Deploy: \"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/mult-comercial/-/commit/b33d2fb541dcd5e3c1ecf3e2dd3367e2545553db\"},\"insert\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/mult-comercial/-/commit/b33d2fb541dcd5e3c1ecf3e2dd3367e2545553db\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-01-23 14:39:37','2025-01-23 15:00:54'),(349,4,72,'429596','Instalação do módulo Custom URL','{\"ops\":[{\"insert\":\"Olá, time.\\n\\nPor gentileza, podem instalar a opção de \"},{\"attributes\":{\"bold\":true},\"insert\":\"Custom URL Rewrite Management \"},{\"insert\":\"na loja.\\n\"}]}','{\"ops\":[{\"insert\":\"Deploy: \"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/bellenzier/-/commit/bbe1b85a710fc40228f9fdc04fa7412548ead42c\"},\"insert\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/bellenzier/-/commit/bbe1b85a710fc40228f9fdc04fa7412548ead42c\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-01-23 15:31:08','2025-01-23 15:53:02'),(350,2,152,'429535','Instalação do módulo Melhor Envio','{\"ops\":[{\"insert\":\"Bom dia equipe, tudo bem?\\n\\nPor gentileza, poderia instalar na loja o módulo de entrega do melho encio confome a loja \"},{\"attributes\":{\"link\":\"https://www.bellenzier.com.br/\"},\"insert\":\"https://www.bellenzier.com.br/\"},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"insert\":\"Deploy: \"},{\"attributes\":{\"link\":\"https://git2bis.com