t\":\" bistwobis_product_requestquote/product/requestquote\\n\"}]}','Resolvido','Baixa',NULL,'2025-07-17 09:53:02','2025-07-21 08:27:08'),(479,2,198,'438677','QRCode não esta sendo exibido na tela de sucesso','{\"ops\":[{\"insert\":\"Olá Equipe, Bom dia ! \\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" O lojista utiliza o PIX do pagar.me,  acessei o painel do pagar.me com ele via anydesk, gerei uma nova chave, cadastrei os IP\'s e validei o cadastro do webhook.\\n\\nAo finalizar um pedido por pix, gera a chave copie e cola mas não apresenta o QrCode, poderiam verificar por gentileza?\\n\"}]}','{\"ops\":[{\"insert\":\"O bloqueio da imagem do qrcode era devido ao módulo CSP que não estava configurado corretamente.\\n\"}]}','Resolvido','Baixa',NULL,'2025-07-18 10:06:56','2025-07-24 13:59:09'),(480,2,32,'438773','Instalação do módulo Pix do Itaú','{\"ops\":[{\"insert\":\"Boa tarde equipe!\\n\\nPoderia por gentileza, instalar o módulo de Pix do Itaú na loja.\\n\"}]}','{\"ops\":[{\"insert\":\"Deploy: \"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/cachimbos-online/-/commit/7d2c8f2c9383446897f6a69fe37aff6ead1e20e6\"},\"insert\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/cachimbos-online/-/commit/7d2c8f2c9383446897f6a69fe37aff6ead1e20e6\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-07-21 10:46:35','2025-07-21 11:49:25'),(481,2,100,'438727','Remoção do módulo da Sigep','{\"ops\":[{\"insert\":\"Boa tarde equipe!\\n\\nRemover o módulo da Sigep\\n\"}]}','{\"ops\":[{\"insert\":\"Deploy: \"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/tecnoar-compressores/-/commit/9af082166762e27beaa26eee71eecf383a744fe6\"},\"insert\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/tecnoar-compressores/-/commit/9af082166762e27beaa26eee71eecf383a744fe6\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-07-21 13:36:00','2025-07-21 14:29:42'),(482,15,211,'438628','Inclusão campo CNPJ no formulário de orçamento','{\"ops\":[{\"insert\":\"Bom dia Equipe!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Ajuste:\"},{\"insert\":\" O cliente possui um formulário de solicitação de orçamento na loja. Este formulário já possui alguns campos e a solicitação do cliente é a inserção de 2 campos.\\n\\nO primeiro a ser inserido é um campo de CNPJ, para o cliente da loja preencher.\\n\\nO segundo campo é só uma mensagem, sendo a mensagem a seguir: \\\"A solicitação de orçamento será atendida exclusivamente para lojistas com CNPJ ativo no ramo de informática, papelaria ou suprimentos.\\\"\\n\"}]}','{\"ops\":[{\"insert\":\"Deploy: \"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/potencial-suprimentos/-/commit/0d79b56c7d62b26b833beb571033dda56dcc9222\"},\"insert\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/potencial-suprimentos/-/commit/0d79b56c7d62b26b833beb571033dda56dcc9222\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-07-21 14:43:57','2025-08-14 11:04:51'),(483,2,24,'438813','Instalação do módulo de Pagamento Itaú','{\"ops\":[{\"insert\":\"Bom dia equipe!\\n\\nPor gentileza, poderiam instalar o módulo do Pix Itaú na loja conforme a loja Playeasy\\n\"}]}','{\"ops\":[{\"insert\":\"Deploy: \"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/charutos-online/-/commit/150cd177e938d1f5c0e20816f05cec37db3383b2\"},\"insert\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/charutos-online/-/commit/150cd177e938d1f5c0e20816f05cec37db3383b2\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-07-23 08:16:49','2025-07-23 14:20:28'),(484,2,225,'438851','Instalação do método de pagamento Itaú Pix','{\"ops\":[{\"insert\":\"Bom dia equipe!\\n\\nPor gentileza, instalar o módulo Pixa Itaú conforme a loja \"},{\"attributes\":{\"bold\":true},\"insert\":\"Playeasy\"},{\"insert\":\".\\n\"}]}','{\"ops\":[{\"insert\":\"Deploy: \"},{\"attributes\":{\"link\":\"https://git2bis.com