},{\"attributes\":{\"bold\":true},\"insert\":\"Esse foi o retorno:\"},{\"insert\":\"\\nNenhuma entidade com Grupo de Clientes = %customerGroup. ID da Linha: SKU = %SKU, ID do Website: %websiteId, Grupo de Clientes = %customerGroup, Quantidade: %qty.\\n\\nPreciso por favor que vejam isso e retornem uma resposta comprovando o funcionamento pra HR fazer a alteração.\\n\"}]}','{\"ops\":[{\"insert\":\"O valor do campo \'customer_group\' estava como: \'TODOS OS GRUPOS\' sendo que o correto seria: \'ALL GROUPS\'\\n\"}]}','Resolvido','Baixa',NULL,'2025-08-06 16:12:25','2025-08-07 15:58:36'),(501,2,168,'439466','Acesso a Página de Produto Simples','{\"ops\":[{\"insert\":\"Olá Equipe, Bom dia!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" No campo de busca da loja, ao pesquisar pelo \"},{\"attributes\":{\"bold\":true},\"insert\":\"SKU 91151\"},{\"insert\":\" aparece o produto, ao clicar para abrir  produto apresenta o erro abaixo:\\n\\nSegue a URL que retorna no erro: \"},{\"attributes\":{\"link\":\"https://www.wilsonatacado.com.br/sapato-masculino-velluti-5991e-off-white-atacado-4398.html#180=1239&158=1301\"},\"insert\":\"https://www.wilsonatacado.com.br/sapato-masculino-velluti-5991e-off-white-atacado-4398.html#180=1239&158=1301\"},{\"insert\":\"\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\"}]}','{\"ops\":[{\"insert\":\"A variação do produto estava vinculado em dois produtos diferentes e um deles estava desabilidato, ocasionando então, o mau comportamento ao acessar a página do produto.\\n\"}]}','Resolvido','Baixa',NULL,'2025-08-08 10:20:14','2025-08-11 14:03:01'),(502,2,2,'439486','Instalação do módulo Busca','{\"ops\":[{\"insert\":\"Boa tarde equipe!\\n\\nPor gentileza, poderiam instalar o \"},{\"attributes\":{\"bold\":true},\"insert\":\"módulo Busca\"},{\"insert\":\" na loja conforme a loja \"},{\"attributes\":