NULL,'2025-08-28 17:49:19','2025-08-29 10:13:48'),(523,15,232,'440408','Instalação do módulo de Reserva de Estoque','{\"ops\":[{\"insert\":\"Bom dia Equipe! \\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Ajuste:\"},{\"insert\":\" Em conversa com o Eduardo, ele citou a existência de um módulo que desabilita o campo \\\"Saleble Quantity\\\" nas lojas M2.\\n\\nPoderiam instalar em Bisws para que eu possa realizar uma validação junto a cliente? \\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Impacto no Cliente:\"},{\"insert\":\" Explique como esse ajuste beneficiará o cliente ou melhorará a experiência do usuário no e-commerce.\\n\"}]}','{\"ops\":[{\"insert\":\"Deploy: \"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/m2/lojas/fixsafe/-/merge_requests/183\"},\"insert\":\"https://git2bis.com.br/bis2bis/m2/lojas/fixsafe/-/merge_requests/183\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-08-29 10:19:44','2025-08-29 15:58:00'),(524,2,180,'440444','Instalação do módulo Facebook XML','{\"ops\":[{\"insert\":\"Bom dia equipe, tudo bem?\\n\\nPor gentileza, instalar o módulo do facebook XML no loja conforme a loja \"},{\"attributes\":{\"bold\":true},\"insert\":\"Star Móveis Uba\"},{\"insert\":\".\\n\"}]}','{\"ops\":[{\"insert\":\"Deploy: \"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/chocolate-doce/-/commit/aee7bed85e46d19e36c77e7182f2acbdceda0be8\"},\"insert\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/chocolate-doce/-/commit/aee7bed85e46d19e36c77e7182f2acbdceda0be8\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-09-01 11:00:12','2025-09-02 09:53:32'),(525,15,2,'440413','Problema na busca','{\"ops\":[{\"insert\":\"Olá equipe, bom dia!\\n\\nBusca da loja retorna log de erro \\n\"}]}','{\"ops\":[{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-09-01 14:47:24','2025-09-01 17:04:41'),(526,15,233,'440507','Erro ao tentar salvar produto','{\"ops\":[{\"insert\":\"Olá equipe, bom dia!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" Ao tentar salvar qualquer produto na loja, o painel retorna mensagem de erro.\\n\"}]}','{\"ops\":[{\"insert\":\"Bom dia equipe!\\n\\nO erro que estava acontecendo ao salvar os produtos no painel administrativo, era causado pelo alto número de registro de produtos na loja onde o limite máximo da capacidade de registro da tabela catalogrule_product_price no banco de dados havia sido excedido e por isso uma erro era retornado na tela.\\n\\nApós redefinir a capacidade desse campo no banco de dados o comportamento de salvar/alterar as informações do produto no painel administrativo voltaram á funcionar.\\n\\n\"},{\"attributes\":{\"background\":\"#ffffff\",\"color\":\"#5f5f5f\"},\"insert\":{\"image\":\"https://s3.amazonaws.com/movidesk-files/2FBBB9F5E62707B7E26E4215B7A63D4C?AWSAccessKeyId=AKIAWSRCTWGBHCVKCQGD&Expires=1756907510&Signature=hm%2B%2F6CshQNOSAToOp91zbRMv1HA%3D\"}},{\"insert\":\"\\n\\nALTER TABLE `catalogrule_product_price`\\n\\tCHANGE COLUMN `rule_product_price_id` `rule_product_price_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT AFTER `earliest_end_date`;\\n\\n\"}]}','Resolvido','Baixa',NULL,'2025-09-02 09:57:42','2025-09-02 13:48:07'),(527,2,62,'440627','Atualização do módulo Gerenciador de Script','{\"ops\":[{\"insert\":\"Boa tarde equipe, tudo bem?\\n\\nPor gentileza atualizar o módulo Gerenciador de Script para a versão 1.1.2 conforme a loja Entre Trilhas\\n\"}]}','{\"ops\":[{\"insert\":\"Deploy: \"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/prontoveterinario/-/commit/76cb0536911a47b96c457ec34c7c3315735bee7f\"},\"insert\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/prontoveterinario/-/commit/76cb0536911a47b96c457ec34c7c3315735bee7f\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-09-02 13:56:08','2025-09-03 08:41:04'),(528,15,235,'440289','A