0,'440398','Ajuste do móduo Configuração do Pagamento','{\"ops\":[{\"insert\":\"Olá Equipe, Boa tarde!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" A loja possui um módulo em \"},{\"attributes\":{\"italic\":true},\"insert\":\"Sistema > Configuração > Métodos de Pagamento > Configurações de Pagamento\"},{\"insert\":\", que permite definir um valor mínimo de pedido por método de pagamento. No entanto, essa configuração não está sendo aplicada corretamente no checkout.\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\\n\"}]}','{\"ops\":[{\"insert\":\"Erro de configuração do módulo e esta descrito no ticket\\n\"}]}','Resolvido','Baixa',NULL,'2025-09-04 08:50:43','2025-09-05 15:40:13'),(533,2,198,'440671','Aplicação de Frete Grátis no carrinho','{\"ops\":[{\"insert\":\"Olá Equipe, Bom dia!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" Crie uma promoção de carrinho de frete grátis somente com a restrição de subtotal acima de R$ 299,00, mas a regra não aplicou, a loja utiliza o método de entrega correios.\\n\"}]}','{\"ops\":[{\"insert\":\"No banco de dados, o atributo feed_method estava duplicado e por isso quando o codigo consultava esse atributo sempre vinha o registro errado e por isso o valor da promoção não era aplicado.\\n\"}]}','Resolvido','Baixa',NULL,'2025-09-04 13:47:28','2025-09-08 13:43:20'),(534,15,96,'440800','Instalação do módulo Gubee','{\"ops\":[{\"insert\":\"Equipe, boa tarde.\\n\\nPoderiam instalar o módulo da Gubee e o Stock Movements na loja?\\n\"}]}','{\"ops\":[{\"insert\":\"Deploy: \"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/auraepele/-/commit/2b045c1d8f0b5d540bddc4c998c92459d1f9066f\"},\"insert\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/auraepele/-/commit/2b045c1d8f0b5d540bddc4c998c92459d1f9066f\"},{\"ins