Cama in Box\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Caminho do módulo no admin:\"},{\"insert\":\" Lojas > Configuração Extensões > Darkmode\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/m2/lojas/harmonia-musical/-/commit/e445228c63e5238d90f10ffbe268434d7d92f1a6\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção.\\n\"}]}','Resolvido','Baixa',NULL,'2025-10-15 09:41:42','2025-11-17 08:29:38'),(576,15,151,'442343','Ação de salvar produto no painel não funciona','{\"ops\":[{\"insert\":\"Olá equipe, bom dia!\\n\\nAo salvar o produto, o painel volta para a tela inicial e não salva.\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Produto testado:\"},{\"insert\":\" 1947753214027\\n\"}]}','{\"ops\":[{\"insert\":\"O problema foi causado por uma má configuração do GoCache que impedia a requisição de completar o processo de edição.\\n\"}]}','Resolvido','Baixa',NULL,'2025-10-16 08:25:03','2025-10-16 17:06:12'),(577,5,148,'442369','Instalação do módulo Grids Customizáveis','{\"ops\":[{\"insert\":\"Olá prezados,\\n\\npor gentileza, poderam instalar o módulo de Grids Personalizado?\\n\"}]}','{\"ops\":[{\"insert\":\"Como combinado, o deploy será feito na segunda-feira no primeiro horário.\\n\\nO merge request gera um conflito que precisou ser ajustado manualmente, assim, quando for fazer o deploy é só executar o comando: \"},{\"attributes\":{\"bold\":true},\"insert\":\"git push origin master\"},{\"insert\":\" e \"},{\"attributes\":{\"bold\":true},\"insert\":\"criar uma nova tag\"},{\"insert\":\".\\n\\n\"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/cerealista-express/-/commit/57fee028e7e51a9ec7d460dc55a0522323765770\"},\"insert\":\"Deploy realizado!\"},{\"insert\":\"\\n\\n\"}]}','Resolvido','Baixa',NULL,'2025-10-16 17:10:00','2025-10-20 15:10:02'),(578,2,189,'442379','Instalação do método de pagamento Rede','{\"ops\":[{\"insert\":\"Boa tarde Equipe! \\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Poderiam por gentileza instalar o modulo:\"},{\"insert\":\" Método de pagamento Rede \\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Loja de referência:\"},{\"insert\":\" \"},{\"attributes\":{\"link\":\"https://www.revestpaper.com.br/\"},\"insert\":\"Revest Paper\"},{\"insert\":\" \\n\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/cikala/-/commit/315a424088d421760dcfeb2158c37636771767be\"},\"insert\":\"Deploy\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-10-17 09:23:19','2025-10-20 17:39:55'),(579,2,26,'442439','Alterar Status do Pedido #000082480','{\"ops\":[{\"insert\":\"Bom dia Equipe!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Ajuste:\"},{\"insert\":\" Por gentileza alterar o status do pedido para completo \"},{\"attributes\":{\"bold\":true},\"insert\":\"#000082480\"},{\"insert\":\"\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\\n\"}]}','{\"ops\":[{\"insert\":\"Foi criado um script SQL para corrigir o status do pedido.\\n\\n\"},{\"attributes\":{\"link\":\"https://bis2bis.bitrix24.com.br/company/personal/user/119/tasks/task/edit/9599/\"},\"insert\":\"Task da infra\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-10-17 16:02:45','2025-10-21 10:15:13');
INSERT INTO `tickets` VALUES (580,15,76,'442341','Correção do preço do produto do Compre Junto no Carrinho de Compras','{\"ops\":[{\"insert\":\"Olá Equipe, Boa tarde ! \\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" O \\\"Compre Junto\\\" da loja permite que, na página do carrinho, mais unidades dos produtos sejam inseridos no carrinho com o valor do desconto. Isso não deveria ocorrer.\\n\\nPoderiam ajustar para que o carrinho não permita inserir mais unidades dos produtos marcados como \\\"Compre Junto\\\" na compra? \\n\\nO módulo da loja \"},{\"attributes\":{\"link\":\"https://www.izzat.com.br/\"},\"insert\":\"Izzat\"},{\"insert\":\" opera da maneira correta e pode ser usado como exemplo.\\n\\nAnexos: \"},{\"attributes\":{\"link\":\"https://www.romerodistribuidora.com.br/receptor-digital-intelbras-de-tv-via-satelite-sat-hd-regional-rds830-4140034.html\"},\"insert\":\"RECEPTOR DIGITAL INTELBRAS DE TV VIA SATELITE SAT HD REGIONAL RDS830 - 4140034\"},{\"insert\":\"\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/romerodistribuidora/-/commit/732ce333f8ec4e4645d664794f3f1cdb291ae47e\"},\"insert\":\"Deploy\"},{\"insert\":\" realizado em bisws, assim que testado subir para produção.\\n\"}]}','Resolvido','Baixa',NULL,'2025-10-17 17:31:15','2025-10-21 17:07:01'),(581,2,157,'439802','Criar placeholder para H1 categorias','{\"ops\":[{\"attributes\":{\"bold\":true},\"insert\":\"Descrição da Melhoria:\"},{\"insert\":\" Atualmente, ao alterar o nome de uma categoria na plataforma, essa modificação reflete em dois locais:\\n\\nMenu do site\"},{\"attributes\":{\"list\":\"bullet\"},\"insert\":\"\\n\"},{\"insert\":\"Tag H1 da categoria\"},{\"attributes\":{\"list\":\"bullet\"},\"insert\":\"\\n\"},{\"insert\":\"\\nA necessidade identificada é criar um novo campo denominado \"},{\"attributes\":{\"bold\":true},\"insert\":\"“Título da página”\"},{\"insert\":\", que seja independente do campo \"},{\"attributes\":{\"bold\":true},\"insert\":\"“Nome”\"},{\"insert\":\".\\n\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Regras da Implementação:\"},{\"insert\":\" O campo \"},{\"attributes\":{\"bold\":true},\"insert\":\"“Nome”\"},{\"insert\":\" permanecerá responsável pelo título exibido no menu do site.\\n\\nO novo campo \"},{\"attributes\":{\"bold\":true},\"insert\":\"“Título da página”\"},{\"insert\":\" deverá ser editável diretamente pela plataforma.\\n\\nEsse novo campo será utilizado para exibição da tag <h1> na página da categoria.\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Exemplo de aplicação:\"},{\"insert\":\"\\n<h1>Título da página</h1>\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Processo de Implementação:\"},{\"insert\":\" \\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Homologação:\"},{\"insert\":\" Todas as alterações serão primeiramente implementadas em um ambiente de teste bisws, para garantir a funcionalidade e a integridade do processo. \\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Validação:\"},{\"insert\":\" Realização de testes intensivos para confirmar que a nova funcionalidade opera conforme o esperado sem interrupções.\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Lançamento em Produção:\"},{\"insert\":\" Após a conclusão bem-sucedida da fase de testes, a funcionalidade será implementada no ambiente de produção. \\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Adendo:\"},{\"insert\":\" Este orçamento inclui a instalação. No caso de surgirem situações adversas, tais como ajustes adicionais, conflitos entre módulos ou modificações solicitadas, entraremos em contato para revisão do orçamento.\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/concordepr/-/commit/f8fa093424c9e8be61d331ab7396e2fc8c40ed86\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção\\n\"}]}','Resolvido','Baixa',NULL,'2025-10-20 17:47:12','2025-10-22 10:09:48'),(582,2,174,'442524','Atualização do módulo Exportação via Shell','{\"ops\":[{\"insert\":\"Boa tarde equipe!\\n\\nPoderia por gentileza instalar o módulo de Exportação de Planilhas Via Shell\\n\\nLoja de ref.: Concorde PR\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/um-pouko-de-tudo/-/commit/7e789d70bc813bdb13ffd42db5f750a1209eaa9f\"},\"insert\":\"Deploy\"},{\"insert\":\" em bisws\\n\"}]}','Resolvido','Baixa',NULL,'2025-10-21 14:13:42','2025-10-22 09:30:54'),(583,2,224,'442407','Remoção de tarjas de aviso no painel administrativo','{\"ops\":[{\"insert\":\"Boa noite equipe!\\n\\nNo painel administrativo da loja está aparecendo uma tarja de teste e alguns avisos, o lojista solicitou que seja removido, segue:\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\\n\"}]}','{\"ops\":[{\"insert\":\"Na hora que eu inciei a correção a mensagem já não estava mais sendo exibida.\\n\"}]}','Resolvido','Baixa',NULL,'2025-10-21 17:38:55','2025-10-22 13:51:52'),(584,2,75,'442521','Produto com peso de 99kg não foi enviado a integração','{\"ops\":[{\"insert\":\"Olá Equipe, Bom dia!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" \\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"SKU:\"},{\"insert\":\" EAX007\\n\\nAo tentar salvar qualquer informação no cadastro deste produto, é exibida a seguinte mensagem de erro.\\n\\nVale destacar que o peso configurado para o item é de 99 kg. Solicito, por gentileza, que verifiquem o motivo do erro e também o porquê de o produto não estar sendo enviado ao Anymarket.\\n\\nMesmo inserindo apenas “99” no campo de peso, ao salvar o sistema exibe novamente a mensagem de erro, e o campo retorna preenchido com “99.0000”.\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Caminho do módulo:\"},{\"insert\":\" Integrações > Anymarket\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/lojademoveisonline/-/commit/7f37bbc414b02929a232da6a235e3d69acb61ec8\"},\"insert\":\"Merge Request\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-10-22 15:04:04','2025-10-23 09:15:13'),(585,15,141,'442568','Instalação do módulo Stock Movements','{\"ops\":[{\"insert\":\"Boa tarde equipe!\\n\\nPodera por gentileza instalar o móudlo \"},{\"attributes\":{\"bold\":true},\"insert\":\"Stock Movements\"},{\"insert\":\" igual a loja \"},{\"attributes\":{\"bold\":true},\"insert\":\"Astro Distribuidora\"},{\"insert\":\"?\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/isomedicalredesign/-/commit/4adb61e7ab03683a94be482625a1654a910a7de9\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção\\n\"}]}','Resolvido','Baixa',NULL,'2025-10-23 10:54:08','2025-10-23 14:04:38');
INSERT INTO `tickets` VALUES (586,2,49,'442542','Ordenar Categoria por posição','{\"ops\":[{\"insert\":\"Olá Equipe, Bom dia!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\"\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Categoria:\"},{\"insert\":\" \"},{\"attributes\":{\"link\":\"https://www.editoraculturacrista.com.br/colecao-crer-e-ser.html\"},\"insert\":\"Coleção Crer e Ser\"},{\"insert\":\"\\nO lojista realizou a ordenação dos produtos pela coluna “posição” dentro da categoria, porém a alteração não está refletindo na loja.\\n\\nVerifiquei que a configuração de ordenação por “últimos produtos cadastrados”, que poderia sobrepor a posição, já estava desabilitada. \\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Caminho do módulo:\"},{\"insert\":\" Sistema > catálogo > catálogo > Listagem de produtos.\\n\\nExecutei o cache e a atualização do índice pelo admin e pelo bot, e solicitei à Yara a limpeza do cache, mas o posicionamento ainda não foi aplicado.\\n\\nPor gentileza, poderiam verificar essa situação?\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/editoraculturacrista/-/commit/ba8d6bbb9981596f2596e455d504df2ce769fb27\"},\"insert\":\"Deploy\"},{\"insert\":\" realizado!\\n\"}]}','Resolvido','Baixa',NULL,'2025-10-23 14:30:43','2025-10-27 08:46:12'),(587,2,238,'442629','Atualização do módulo Google Shopping API','{\"ops\":[{\"insert\":\"Bom dia Equipe!\\nPoderiam por gentileza instalar o modulo: Google Shopping API\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Loja de referência:\"},{\"insert\":\" \"},{\"attributes\":{\"link\":\"https://www.tycket.com.br/\"},\"insert\":\"Tycket\"},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/mvictoriaperfume/-/commit/3d18d46461103a34c1d81b007efec9c1126b77fb\"},\"insert\":\"Deploy\"},{\"insert\":\" realizado.\\n\"}]}','Resolvido','Baixa',NULL,'2025-10-24 14:53:19','2025-10-27 09:08:58'),(588,2,160,'442638','Instalação do módulo de Grid Personalizada','{\"ops\":[{\"insert\":\"Olá prezados!\\n\\nPor gentileza, poderia instalar o módulo Grid Personalizado?\\n\\nLoja de ref.: Fam DVD\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/astrodistribuidora/-/commit/b95a52a4a04f9f3086c6ee02052fe2f33d5a218d\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção resolvido\\n\"}]}','Resolvido','Baixa',NULL,'2025-10-24 16:51:46','2025-10-28 08:56:29'),(589,2,160,'442671','Instalação Modulo do Omny Checkout','{\"ops\":[{\"insert\":\"Boa tarde equipe!\\n\\nPoderia por gentileza instalar o óudlo Omny Checkout\\n\\nLoja de referência: \"},{\"attributes\":{\"link\":\"https://www.donacastanha.com.br/\"},\"insert\":\"Dona Castanha\"},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/astrodistribuidora/-/commit/c9f5b15d5951cf578d72b5b109d043c41e9f8f45\"},\"insert\":\"Deploy\"},{\"insert\":\" em bisws\\n\"}]}','Resolvido','Baixa',NULL,'2025-10-27 10:00:16','2025-10-27 11:12:39'),(590,2,160,'442728','Atualização do módulo Omny Checkout','{\"ops\":[{\"insert\":\"Bom dia equipe, tudo bem?\\nSegue as informações enviadas pela Omny:\\nCom relação apontando no módulo homologação segue branch: \"},{\"attributes\":{\"link\":\"https://bitbucket.org/omnybrasil/magento1/src/dev/\"},\"insert\":\"Repositório\"},{\"insert\":\"\\nRepositório é o mesmo, porém a branch é \"},{\"attributes\":{\"bold\":true},\"insert\":\"dev\"},{\"insert\":\".\\n\"}]}','{\"ops\":[{\"insert\":\"29/10/2025\\n\"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/astrodistribuidora/-/commit/a2d80e64b07339d0bc9082b38ae62c74468b76b4\"},\"insert\":\"Atualização do módulo \"},{\"insert\":\"\\n\\n\"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/astrodistribuidora/-/commit/a2d80e64b07339d0bc9082b38ae62c74468b76b4\"},\"insert\":\"Deploy\"},{\"insert\":\" em bisws\\n\"}]}','Resolvido','Baixa',NULL,'2025-10-28 10:22:58','2025-10-29 14:03:31'),(591,2,37,'442523','Configuração do Selo do Google Avaliações do Consumidor','{\"ops\":[{\"insert\":\"Olá Equipe, Boa tarde!\\n\\nDescrição do Problema: O selo de avaliação não está sendo exibido corretamente no front.\\nA loja possui avaliações, porém o selo aparece como “sem avaliação”.\\n\\nA conta foi verificada e não possui inconsistências. Caso houvesse, poderia impactar na exibição da avaliação da loja.\\n\\nAção solicitada: Verificar o motivo pelo qual o selo não está refletindo corretamente no front e ajustar a exibição.\\n\"}]}','{\"ops\":[{\"insert\":\"o script esta instalado mas não aparece, pode ser uma má configuração no Google Merchant Center\\n\\n\"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/fisicofarma/-/commit/c1f3b7cbd4f1c7dc870c4d5426ac923402ef21e1\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção\\n\\nLink da documentação:\\n\"},{\"attributes\":{\"link\":\"https://support.google.com/merchants/answer/14632921\"},\"insert\":\"https://support.google.com/merchants/answer/14632921\"},{\"insert\":\"\\n\"},{\"attributes\":{\"link\":\"https://support.google.com/merchants/answer/14629205?sjid=6560173227998214076-SA\"},\"insert\":\"https://support.google.com/merchants/answer/14629205?sjid=6560173227998214076-SA\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-10-28 11:21:50','2025-11-18 15:44:40'),(592,1,160,'442828','Log Retriver Omny','{\"ops\":[{\"insert\":\"Bruno!\\n\\nConforme conversamos, preciso que as logs da Omny homolog apareçam no log retriever, assim como é na dona castanha.\\n\\nomny_checkout.log\\n\"}]}','{\"ops\":[{\"insert\":\"O arquivo de log não está sendo gerado e exibido no Log Retriver, devido a um falta de um parâmetro no método responsável por gerar o arquivo de log, como mostra o link a baixo:\\n\\nhttps://bitbucket.org/omnybrasil/magento1/src/84120848f33368a2162b29889d11fdbf07d7314e/app/code/local/Omny/Checkout/Helper/Data.php#lines-25\\n\\nNo método log(...) não foi declarado o último parâmetro(com o valor: true) que é responsável por força a escrita do registro de log e por isso o arquivo não era gerado e consequentimente não era listado no Log Retriver.\\n\\nCom tudo, a empresa responsável pela manutenção do módulo deverá ajustar esse detalhe visto que eu não possuo permissão para ajustar esse detalhe.\\n\"}]}','Resolvido','Baixa',NULL,'2025-10-29 14:43:46','2025-10-29 17:28:40'),(593,5,58,'442841','Instalação do módulo de Brinde','{\"ops\":[{\"insert\":\"Olá prezados!\\n\\nPor gentileza, poderia instalar o módulo: Brinde\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/kimonosdojo/-/commit/262dfdea35367109f3131d0f541bd3c397426d65\"},\"insert\":\"Deploy\"},{\"insert\":\" realizado em produção\\n\"}]}','Resolvido','Baixa',NULL,'2025-10-30 16:32:23','2025-10-31 09:34:27'),(594,2,58,'442899','Erro na criação de regra do Compre Junto','{\"ops\":[{\"insert\":\"Olá Equipe, Boa tarde!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" Acessando o módulo do compre junto em: \"},{\"attributes\":{\"bold\":true},\"insert\":\"Catálogo > Compre junto > Regras\"},{\"insert\":\", montar uma regra e tentar salvar a regra, o botão salvar não está retornando nenhuma ação e a promoção não é criada.\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/kimonosdojo/-/commit/a6e7aef7930f491af7941467e21e06d5882937ed\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção\\n\"}]}','Resolvido','Baixa',NULL,'2025-10-31 11:23:59','2025-11-03 08:29:40'),(595,15,18,'442968','Instalação do módulo Exportação via Shell','{\"ops\":[{\"insert\":\"Boa tarde equipe!\\n\\nPoderia por gentileza instalar o módulo de \"},{\"attributes\":{\"bold\":true},\"insert\":\"Exportação via Shell\"},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-11-03 09:16:08','2025-11-07 12:20:13');
INSERT INTO `tickets` VALUES (596,15,58,'442536','Personalização do produto no carrinho de compras','{\"ops\":[{\"insert\":\"Olá Equipe, Bom dia!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" O campo \\\"Nome\\\" já exibe uma obrigatoriedade de preenchimento quando o idioma do bordado é selecionado. Porém, caso seja inserido um espaço no campo, o preenchimento é aceito e a personalização é cobrada.\\n\\nÉ possível ajustar este campo para que ele exija pelo menos uma letra para que o produto seja inserido no carrinho?\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/kimonosdojo/-/commit/a570c98a4e52730b3f5c44c102eb2291cd5bc868\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção\\n\\n\"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/m1/modulos/dev-tools/google/google-analytics/-/commit/71c7a8813e6cfd81cb746f9cda4a0ff6a14b89e6\"},\"insert\":\"Commit\"},{\"insert\":\" da resolução do conflito\\n\"}]}','Resolvido','Baixa',NULL,'2025-11-03 12:02:07','2025-11-06 16:53:58'),(597,2,160,'442527','Melhoria no relatório de Pedidos','{\"ops\":[{\"insert\":\"Boa tarde Equipe!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Ajuste:\"},{\"insert\":\" Conforme informado no ticket \"},{\"attributes\":{\"bold\":true},\"insert\":\"442340\"},{\"insert\":\":\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Análise:\"},{\"insert\":\" A cron \"},{\"attributes\":{\"bold\":true},\"insert\":\"aggregate_sales_report_order_data\"},{\"insert\":\" é responsável por gerar os dados do relatório de pedidos. Esses dados são armazenados na tabela \"},{\"attributes\":{\"bold\":true},\"insert\":\"sales_order_aggregated_created\"},{\"insert\":\". Porém, no fluxo desta cron, existe uma filtragem na coleção dos pedidos que é para ignorar os pedidos com estado \"},{\"attributes\":{\"bold\":true},\"insert\":\"pending_payment\"},{\"insert\":\" e \"},{\"attributes\":{\"bold\":true},\"insert\":\"new\"},{\"insert\":\". Por isso que existe essa diferença de quantidade de pedido no relatório de pedido e na grade de pedidos, pois na grade exibe os pedidos de todos os estados. \\n\\nPreciso que ao acessar o relatório em: \"},{\"attributes\":{\"bold\":true},\"insert\":\"relatório > vendas > pedidos\"},{\"insert\":\", apareçam todos os pedidos, inclusive os pedidos com estado de \"},{\"attributes\":{\"bold\":true},\"insert\":\"new\"},{\"insert\":\" e \"},{\"attributes\":{\"bold\":true},\"insert\":\"pending_payment\"},{\"insert\":\". \\n\\nPor gentileza, poderiam ajustar?\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Modulo:\"},{\"insert\":\" \"},{\"attributes\":{\"link\":\"https://www.astrodistribuidora.com/index.php/admin/report_sales/sales/key/bac78795a900e86b0b6fa8c308d6f1e3/\"},\"insert\":\"Relatório de pedido\"},{\"insert\":\"\\n\\nAnexos: \\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/astrodistribuidora/-/commit/dade24cf3953d98750a1795ab6f9411c5c115812\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção\\n\"}]}','Resolvido','Baixa',NULL,'2025-11-07 15:47:15','2025-11-10 13:30:46'),(598,2,201,'443139','Atualização do método de pagamento Banco do Brasil','{\"ops\":[{\"insert\":\"Boa tarde equipe!\\n\\nPoderia por gentileza instalar o módulo do Banco do Brasil\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/gama4x4/-/commit/bc2070ecd6f4c62a7f512bcd40744f964ab22676\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção\\n\\n\"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/gama4x4/-/commit/e629e938c723fcbfe2358cab917a0908735eaf35\"},\"insert\":\"Deploy 2\"},{\"insert\":\"\\n\\n\"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/gama4x4/-/commit/20b9db6a182ae33beebc7d9869921f85bd5fd22d\"},\"insert\":\"Deploy 3\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-11-10 16:05:49','2025-12-03 15:47:54'),(599,15,58,'443294','Instalação do módulo envio de e-mail ao cancelar pedido','{\"ops\":[{\"insert\":\"Bom dia equipe!\\n\\nPoderia por gentileza instalar o módulo de envio E-mail transacional para pedidos cancelados?\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/kimonosdojo/-/commit/bddda9fddb7f5b5d282afb48fe44d9ff22fa5e61\"},\"insert\":\"Deploy\"},{\"insert\":\" realizado em produção\\n\"}]}','Resolvido','Baixa',NULL,'2025-11-11 15:04:59','2025-11-12 16:09:02'),(600,15,189,'443318','Instalação do módulo de Recompra','{\"ops\":[{\"insert\":\"Bom dia Equipe!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Poderiam por gentileza instalar o modulo:\"},{\"insert\":\" Poderiam atualizar a loja para que os pedidos cancelados constem com a função de recompra? \\n\\nLoja de referência: \"},{\"attributes\":{\"link\":\"https://www.astrodistribuidora.com/\"},\"insert\":\"Astro Distribuidora\"},{\"insert\":\"\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\\n\"}]}','{\"ops\":[{\"insert\":\"O motivo do botão Recomprar não esta aparecendo é por conta do produto esta sem estoque.\\n\"}]}','Resolvido','Baixa',NULL,'2025-11-12 18:00:02','2025-11-13 09:21:19');
INSERT INTO `tickets` VALUES (601,15,2,'443422','Imagens não convertem para a extensão .webp','{\"ops\":[{\"insert\":\"Olá equipe!\\n\\nAtivei o módulo webp, porém, as imagens não estão sendo convertidas.\\n\\nLimprei o cache e reindexei a loja, porém, sem sucesso.\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\nO mesmo problema já havia acontecido antes e reportado no ticket: #442990\\n\\n\"}]}','{\"ops\":[{\"insert\":\"Foi necessário atualizar o módulo WebP\\n\"}]}','Resolvido','Baixa',NULL,'2025-11-13 11:06:32','2025-11-13 13:29:10'),(602,15,160,'443552','Atualização Branch Produção Astro Distribuidora','{\"ops\":[{\"insert\":\"Boa tarde Equipe! \\n\\nPoderiam por gentileza instalar o modulo: Omny checkout\\n\\nEvidencias: \"},{\"attributes\":{\"link\":\"https://bitbucket.org/omnybrasil/magento1/src/master/\"},\"insert\":\"Bitbucket\"},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/astrodistribuidora/-/commit/f9b46a84322456c0546bec86607ca1747e974c42\"},\"insert\":\"Módulo instalado\"},{\"insert\":\" em Homologação\\n\\nTicket fechado pela Amanda\\n\"}]}','Resolvido','Baixa',NULL,'2025-11-13 14:28:32','2025-11-17 08:41:50');
INSERT INTO `tickets` VALUES (603,15,27,'443558','Duplicação de promoção em variações do produto','{\"ops\":[{\"insert\":\"Olá Equipe, Boa tarde ! \\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" As promoções de catálogo da loja estão com um erro na aplicação em produtos configuráveis.\\n\\nTendo como referência o produto \"},{\"attributes\":{\"link\":\"https://www.berettadobrasil.com.br/colete-beretta-uniform-pro-20-20-preto-e-laranja-903.html\"},\"insert\":\"Uniforme Pro 20\"},{\"insert\":\" , existe uma promoção criada para conceder R$ 200 reais de desconto no produto. O desconto é aplicado corretamente, porém, ao selecionar uma variação de tamanho, o desconto é duplicado, asism exibindo o valor incorreto na página do produto.\\n\\nEfetuei alguns testes, como deixando apenas o produto configuravel na promoção, porém, o erro persistiu. Caso a promoção seja desativada, os produtos retornam ao preço original, o que comprova que apenas essa promoção está cadastrada no item.\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Regra criada:\"},{\"insert\":\" Coletes BF 2025\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/berettadobrasil/-/commit/ae2c9909798466ab8acb28a7ce0a5c702302ba12\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção\\n\"}]}','Resolvido','Baixa',NULL,'2025-11-14 14:14:02','2025-11-19 09:03:00'),(604,15,69,'443461','Imagens do Lazyload já iniciadas ao acessar a página','{\"ops\":[{\"insert\":\"Olá Equipe, Boa tarde!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" A loja possui um módulo de Lazyload ativado. Porém, ao acessar a loja, as imagens já parecem carregar de imediato, sem o lazyload.\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Obs:\"},{\"insert\":\" No ambiente bisws o lazy load parece ocorrer corretamente, porém, na loja produção não.\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"insert\":\"O lazyload estava carregando as imagens antes mesmo que o scroll da página chegasse nas imagens, causando a impressão que o carregamento lento não estava funcionando.\\n\"}]}','Resolvido','Baixa',NULL,'2025-11-17 09:17:28','2025-11-19 11:58:28'),(605,15,241,'443735','Inclusão da opção Sisprime no Deposito Bancário','{\"ops\":[{\"insert\":\"Bom dia Equipe! \\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Ajuste:\"},{\"insert\":\" Poderiam inserir no módulo de Depósito bancário a opção do banco Sisprime?\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Modulo:\"},{\"insert\":\" Depósito Bancário(Módulo offline)\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\nÍcone do Sisprime\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/cutelaria-costal/-/commit/7df2298349a73f7a7bd9de878a99ea26d1ceaa8c\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção\\n\\n\"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/cutelaria-costal/-/commit/20fc7d9c9bdb0f4194bd8b1d671c063ee16f0852\"},\"insert\":\"Deploy\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-11-19 14:47:25','2025-11-24 12:03:45'),(606,15,43,'443537','Icone da loja na rede de pesquisa do Google','{\"ops\":[{\"insert\":\"Olá equipe, bom dia!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do problema:\"},{\"insert\":\" A favicon da loja está incorreta no Google. Acessando o site, a mesma está correta.\\n\\nPoderiam validar se o envio da favicon para o Google stá sendo realizada corretamente?\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"insert\":\"As configurações da loja estão corretas e não há nada do nosso lado que possa ser feito, o correto é contatar o time de suporte do Google para alinhar o carreganto da favicon da loja na rede de pesquisa do Google.\\n\"}]}','Resolvido','Baixa',NULL,'2025-11-24 09:54:28','2025-11-24 09:55:58'),(607,15,226,'443837','Instalação do módulo Darkmode','{\"ops\":[{\"insert\":\"Bom dia equipe!\\n\\nPoderia por gentileza instalar o módulo Darkmode?\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/m2/lojas/chocolandia/-/commit/7a331349278ef89d0d65f5ef64694dd601f96861\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção\\n\"}]}','Resolvido','Baixa',NULL,'2025-11-24 15:05:06','2025-11-24 15:17:26');
INSERT INTO `tickets` VALUES (608,15,161,'443540','Edição do email transacional','{\"ops\":[{\"insert\":\"Bom dia Equipe!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Ajuste:\"},{\"insert\":\" O cliente deseja realizar uma alteração no titulo dos e-mails transacionais de envio e reembolso. Porém, analisando o painel da loja, constatei que estes e-mails não constam como editaveis na lista de e-mails de transação. Poderiam verificar?\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"insert\":\"Para tornar o campo editável é só retirar o estado do campo do modo Valor padrão.\\n\"}]}','Resolvido','Baixa',NULL,'2025-11-24 17:54:38','2025-11-25 16:48:53');
INSERT INTO `tickets` VALUES (609,15,197,'443872','Exibição limitada de posts na página Blog do site','{\"ops\":[{\"insert\":\"Olá equipe, boa tarde! \\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" O módulo do blog localiza 17 postagens ao todo, porém, o módulo não exibe uma segunda página e não permite exibir mais do que 9 resultados.\\n\\nPoderiam ajustar?\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"insert\":\"O módulo Blog não estava com a configuração de itens por página configurado.\\n\"}]}','Resolvido','Baixa',NULL,'2025-11-25 14:44:43','2025-11-25 16:50:04'),(610,15,193,'443925','Produtos integrado aos Pacotes de Produtos não aparecem na página de produtos','{\"ops\":[{\"insert\":\"Olá Equipe, Boa tarde!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" A loja possui pacotes de produto cadastrados, porém, os produtos inseridos no pacote não estão snedi exibidos na página e isso faz com que o pedido fique impossibilitado.\\n\\nPoderiam verificar?\\n\"}]}','{\"ops\":[{\"insert\":\"O motivo pelo o qual os itens que compõe o kit de produtos não estavam aparecendo na página do produto era devido ao módulo FPC que estava cacheando a página e como o template que mostra os itens do kit é um conteúdo dinâmico, a estrutura da página carregava o conteúdo que esta em cache mas não o conteúdo dinâmico devido a uma configuração do módulo FPC.\\n\\nApós a remoção do bloco \'content\' do conteúdo dinâmico e do bloco de carregamento lento os produtos que compõe o kit voltaram a aparecer na página do produto.\\n\"}]}','Resolvido','Baixa',NULL,'2025-11-26 14:24:00','2025-12-01 09:04:30'),(611,15,226,'444008','Instalação do módulo Stock Movements','{\"ops\":[{\"insert\":\"Boa tarde equipe!\\n\\nPoderia por gentileza instalar o módulo Inventory Replort (Stock Movements)?\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Loja de referência:\"},{\"insert\":\" \"},{\"attributes\":{\"link\":\"https://www.evolusom.com.br/\"},\"insert\":\"Evolusom\"},{\"insert\":\"\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"insert\":\"Deploy realizado em produção juntamente com as alterações do Léo \\n\"}]}','Resolvido','Baixa',NULL,'2025-11-27 10:01:31','2026-01-21 10:05:29'),(612,5,1,'443934','Instalação do módulo Busca Avançada','{\"ops\":[{\"insert\":\"Olá prezados!\\n\\nPor gentileza, poderia instalar o módulo Busca Avançada\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/editoravida/-/commit/01fb73f57e442d21f0cd019e11715702f2ecbe65\"},\"insert\":\"Deploy\"},{\"insert\":\" agendado para segunda-feira(01/12)\\n\"}]}','Resolvido','Baixa',NULL,'2025-11-28 07:43:52','2025-12-01 08:19:07'),(613,2,183,'443961','Instalação do módulo FPC','{\"ops\":[{\"insert\":\"Bom dia equipe!\\n\\nPoderia por gentileza instalar o módulo FPC\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/lojaludica/-/commit/f3215fb1a8ce2f1a55d198fc189a193f683ff157\"},\"insert\":\"Deploy\"},{\"insert\":\" agendados para próxima segunda-feira(01/12)\\n\"}]}','Resolvido','Baixa',NULL,'2025-11-28 08:43:36','2025-12-01 08:31:22'),(614,2,34,'444010','Atualização do módulo Google Shopping','{\"ops\":[{\"insert\":\"Boa tarde equipe!\\n\\nPoderia por gentileza instalar o módulo Google Shopping\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/sonhart/-/commit/d7cdedbaae9a97038065168a70a9ad1d78945715\"},\"insert\":\"Deploy\"},{\"insert\":\" agendado para segunda-feira(01/12)\\n\"}]}','Resolvido','Baixa',NULL,'2025-11-28 10:11:20','2025-12-01 16:53:52');
INSERT INTO `tickets` VALUES (615,15,242,'444052','Instalação do módulo Gerencimento de Status do Pedido','{\"ops\":[{\"insert\":\"Boa tarde Equipe!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Poderiam por gentileza instalar o modulo:\"},{\"insert\":\" Gerenciador de Status do Pedido\\n\\nA loja não possui a função de gerenciar Status, para alterar status de pedidos e cancelar.\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Loja de referência:\"},{\"insert\":\" \"},{\"attributes\":{\"link\":\"https://www.cikala.com.br/\"},\"insert\":\"Cikala\"},{\"insert\":\"\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/rm-makeup/-/commit/47d6586b309a186b582e92a9abce52dc1db12fb0\"},\"insert\":\"Deploy\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-12-01 09:40:21','2025-12-01 13:35:35'),(616,15,49,'444128','Instalação do módulo de Exportação via Shell','{\"ops\":[{\"insert\":\"Bom dia equipe!\\n\\nPoderia por gentileza instalar o módulo de \"},{\"attributes\":{\"bold\":true},\"insert\":\"Exportação via Shell\"},{\"insert\":\" igual a loja \"},{\"attributes\":{\"link\":\"https://loja.sonhart.com.br/\"},\"insert\":\"Sonhart\"},{\"insert\":\"?\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/editoraculturacrista/-/commit/9ec744baa4eee5fd015e704811aa2028f59044a4\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção.\\n\"}]}','Resolvido','Baixa',NULL,'2025-12-01 18:33:03','2025-12-02 08:47:39'),(617,2,108,'444131','Atualização do módulo GA4','{\"ops\":[{\"insert\":\"Bom dia equipe!\\n\\nPoderia por gentileza atualizar o módulo Google Analytics igual a loja Tycket\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/cama-carro-do-brasil/-/commit/0a0765b0a0878a47f77e2581dadb7b42116e4293\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção\\n\"}]}','Resolvido','Baixa',NULL,'2025-12-02 08:52:48','2025-12-02 11:07:08'),(618,15,236,'443706','Atributo Status do produto não aparece na exportação','{\"ops\":[{\"insert\":\"Boa tarde Equipe! \\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Ajuste:\"},{\"insert\":\" A exportação de planilha em \"},{\"attributes\":{\"bold\":true},\"insert\":\"Sistema > Exportar\"},{\"insert\":\" ocorre de modo em que a planilha não consta com a coluna \"},{\"attributes\":{\"bold\":true},\"insert\":\"\\\"Status\\\"\"},{\"insert\":\".\\n\\nÉ possível exportar essa informação de alguma maneira?\\n\\nExportação realizada na \"},{\"attributes\":{\"link\":\"https://cimparts.bisws.com.br/\"},\"insert\":\"Cimparts Homologação\"},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"insert\":\"O atributo \"},{\"attributes\":{\"bold\":true},\"insert\":\"status\"},{\"insert\":\" que você está procurando no arquivo está nomeado como \"},{\"attributes\":{\"bold\":true},\"insert\":\"product_online (Produto Online)\"},{\"insert\":\" e o seu valor é um binário \"},{\"attributes\":{\"bold\":true},\"insert\":\"0\"},{\"insert\":\" ou \"},{\"attributes\":{\"bold\":true},\"insert\":\"1\"},{\"insert\":\", onde \"},{\"attributes\":{\"bold\":true},\"insert\":\"0 é para produto desabilitado\"},{\"insert\":\" e \"},{\"attributes\":{\"bold\":true},\"insert\":\"1 para produto habilitado\"},{\"insert\":\".\\n\"}]}','Resolvido','Baixa',NULL,'2025-12-03 15:16:00','2025-12-03 15:16:28'),(619,1,100,'442598','Instalação do módulo Page Speed','{\"ops\":[{\"insert\":\"Poderia por gentileza instalar o modulo do pagespeed?\\n\\nEm seguida, encaminhar o ticket ao Frontend para ser efetuado os ajustes necessários no layout.\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/tecnoar-compressores/-/commit/d3a0e7272d12ff66bfac0640cc808f35cc954e42\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção\\n\"}]}','Resolvido','Baixa',NULL,'2025-12-03 15:52:07','2025-12-04 09:16:41'),(620,15,2,'443525','Instalação dos módulos FPC e PageSpeed','{\"ops\":[{\"insert\":\"Favor instalar o FPC e o pagespeed, para otimizarmos a resposta do servidor.\\nApós a instalação, alocar ao time de frontend para configuração\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/velocepneus/-/commit/3e0e8d64cf906a1f763e5bff235c8bea703f84c4\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção\\n\"}]}','Resolvido','Baixa',NULL,'2025-12-04 10:21:41','2025-12-04 15:01:51'),(621,15,100,'444246','XML de Produtos','{\"ops\":[{\"insert\":\"Boa tarde Equipe!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Ajuste:\"},{\"insert\":\" Atualmente o XML gerado pelo módulo \"},{\"attributes\":{\"bold\":true},\"insert\":\"Google XML API\"},{\"insert\":\" puxa o link de apenas uma imagem por produto. \\n\\nPoderiam ajustar para que puxe todas as imagens dos produtos?\\n\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/tecnoar-compressores/-/commit/a2b6bee03d2d27fbbc761a3918dee38bd135a7c1\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção\\n\"}]}','Resolvido','Baixa',NULL,'2025-12-04 15:05:52','2025-12-04 17:39:43'),(622,15,5,'444298','Consulta de status de reembolso do pedido via API','{\"ops\":[{\"insert\":\"Equipe, boa tarde.\\n\\nPoderiam verificar se é possível consultar o status do reembolso do pedido via API?\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\nEu realizei a requisição salesOrderCreditmemoInfo e obtive o resultado abaixo, porém, não tenho certeza se este campo é referente ao status evidenciado no print acima.\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"<state xsi:type=\\\"xsd:string\\\">2</state>\"},{\"insert\":\"\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"insert\":\"O elemento state é o estado em que o reembolso se encontra, no caso dessa loja, a API retornou o código 2 que significar: Devolvido.\\n\\nHá três opções de estado, que são:\\nPendente\"},{\"attributes\":{\"list\":\"ordered\"},\"insert\":\"\\n\"},{\"insert\":\"Devolvido\"},{\"attributes\":{\"list\":\"ordered\"},\"insert\":\"\\n\"},{\"insert\":\"Cancelado\"},{\"attributes\":{\"list\":\"ordered\"},\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2025-12-05 09:25:49','2025-12-05 13:47:22'),(623,15,168,'444092','Redirecionamento de URL','{\"ops\":[{\"insert\":\"Olá Equipe, Boa tarde!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" Subir uma planilha de redirecionamento na loja. O painel acusou que ocorreu tudo corretamentem sem erros, porém, os redirects não estão snedo aplicados. \\n\\nPoderiam verificar?\\n\"}]}','{\"ops\":[{\"insert\":\"Docs: \"},{\"attributes\":{\"link\":\"https://helpdesk.bis2bis.com.br/kb/pt-br/article/409839/redirecionamento-m2?ticketId=&q=\"},\"insert\":\"Criando redirecionamento de URL no Magento 2\"},{\"insert\":\"\\n\\n\"}]}','Resolvido','Baixa',NULL,'2025-12-05 17:50:21','2025-12-08 09:01:35'),(624,2,236,'444318','Imagens incorretas na thumbnails','{\"ops\":[{\"insert\":\"Olá Equipe, Boa tarde!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" Com o módulo Webp habilitado as imagens apresentadas nos produtos na loja não correspondem a imagem cadastrada no painel administrativo.\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Produto de Exemplo:\"},{\"insert\":\" \"},{\"attributes\":{\"link\":\"https://www.cimpecas.com.br/vela-ignicao.html\"},\"insert\":\"Vela Ignição\"},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"insert\":\"Com a atualizaçãod o módulo para Renomear as Imagens e após a recarga de dados por parte da Integrado, as imagens passarão a se comportar normalmente.\\n\"}]}','Resolvido','Baixa',NULL,'2025-12-08 09:45:25','2025-12-10 09:11:01'),(625,2,160,'444365','Atualização do módulo Omny Checkout','{\"ops\":[{\"insert\":\"Bom dia equipe!\\n\\nPoderia por gentileza atualizar o módulo em Homologação e Produção.\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/astrodistribuidora/-/commit/9087117c58e569330eef4c466ddcc6e79d2901f3\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção\\n\"}]}','Resolvido','Baixa',NULL,'2025-12-09 13:15:59','2025-12-09 16:48:57'),(626,2,69,'444337','Atualização do módulo Retirar na Loja','{\"ops\":[{\"insert\":\"Boa tarde Equipe! \\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Ajuste:\"},{\"insert\":\" Por gentileza, atualizar o módulo da Way pra esse na Staging, esse módulo é o mesmo, mas sem bater na API da Integra.do\\n\\n\"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/m2/modulos/store-pickup/-/tree/feature/12411?ref_type=heads\"},\"insert\":\"Repositório\"},{\"insert\":\" do módulo\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/m2/lojas/way-suplementos-bisws/-/merge_requests/309\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção\\n\"}]}','Resolvido','Baixa',NULL,'2025-12-10 09:18:22','2025-12-10 14:30:04'),(627,2,160,'444455','Atualização do módulo Omny Checkout','{\"ops\":[{\"insert\":\"Bom dia equipe!\\n\\nPoderia por gentileza instalar o módulo Omny Checkout\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/astrodistribuidora/-/commit/ee545f083ed5aece8c0c8fe15de432c81b3afe6e\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção\\n\"}]}','Resolvido','Baixa',NULL,'2025-12-10 14:02:09','2025-12-10 17:49:51'),(628,1,237,'444477','Instalação do módulo de Exportação de Planilhas via Shell','{\"ops\":[{\"insert\":\"Poderia instalar o módulo Shell\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/oticariobranco/-/commit/0e4ea5e7b1167ffa703a872884445142ceaac96a\"},\"insert\":\"Deploy\"},{\"insert\":\" realizado em produção\\n\"}]}','Resolvido','Baixa',NULL,'2025-12-11 09:17:11','2025-12-11 14:00:45'),(629,2,230,'444481','Instalação do módulo GA4','{\"ops\":[{\"insert\":\"Bom dia equipe!\\n\\nPoderia instalar o módulo GA4?\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/grow-plant/-/commit/de52a3ae9574f2d0f898a308bc43509b672fed18\"},\"insert\":\"Deploy\"},{\"insert\":\" realizado em produção\\n\"}]}','Resolvido','Baixa',NULL,'2025-12-11 14:13:45','2025-12-11 16:13:18'),(630,2,168,'444501','Instalação de Gerente de Marcas Google','{\"ops\":[{\"insert\":\"Poderia instalar o modulo Gerente de Marcas Google\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/m2/lojas/wilson-atacado-m2/-/merge_requests/329\"},\"insert\":\"Deploy\"},{\"insert\":\" em produção\\n\"}]}','Resolvido','Baixa',NULL,'2025-12-11 18:09:27','2025-12-15 14:12:49'),(631,15,84,'444523','O valor mínimo do frete gerenciável não está funcionando','{\"ops\":[{\"insert\":\"Olá Equipe, Boa tarde!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" No módulo de frete gerenciavel, a função \\\"Valor mínimo em R$ para esta tabela\\\" não opera como deveria.\\n\\nAo inserir um valor neste campo, a planilha de frete gerenciavel não é exibida na loja, com isso, o frete deixa de funcionar. Poderiam verificar?\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/bananabrasil/-/commit/ba94c88524e28eb7cfa78089fd7edf5951229b8a\"},\"insert\":\"Deploy\"},{\"insert\":\" realizado em produção\\n\"}]}','Resolvido','Baixa',NULL,'2025-12-12 10:26:48','2025-12-15 17:02:50'),(632,2,193,'444539','Atualização do módulo Google Shopping API','{\"ops\":[{\"insert\":\"Bom dia equipe!\\n\\nPoderia por gentileza atualizar o módulo Google Shopping API\\n\\nLoja de ref.: \"},{\"attributes\":{\"link\":\"https://www.tycket.com.br\"},\"insert\":\"Tycket\"},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"insert\":\"