entes no administrativo','{\"ops\":[{\"insert\":\"Olá equipe, bom dia!\\n\\nPainel admin não acessa a aba Clientes.\\n\"}]}','{\"ops\":[{\"insert\":\"O campo Data do Ultimo Pedido não tinha campo adicionado na tabela customgrid_customer\\n\"}]}','Resolvido','Baixa',NULL,'2026-01-13 13:48:37','2026-01-13 15:29:06'),(650,15,244,'445218','Instalação do módulo Mercado Pago','{\"ops\":[{\"insert\":\"Boa tarde equipe!\\n\\nPoderia por gentileza Instalar o módulo Mercado Pago\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/fullturbosparts/-/commit/f97b5676c8af55a53f626ceadb777b50f094d047\"},\"insert\":\"Deploy\"},{\"insert\":\" realizado em produção\\n\"}]}','Resolvido','Baixa',NULL,'2026-01-13 16:00:00','2026-01-14 13:42:14'),(651,7,151,'445200','Instalação do módulo de Autenticação de dois fatores','{\"ops\":[{\"insert\":\"Boa tarde equipe, tudo bem?\\n\\nPodera instalar o módulo de autenticação em dois fatores na Tabacaria da Mata, por gentileza? \\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/m2/lojas/tabacaria-da-mata/-/commit/2953bd4cb0483ee9ca7128c47d0709e4cfd7bc5e\"},\"insert\":\"Deploy\"},{\"insert\":\" realizado na bisws\\n\"}]}','Resolvido','Baixa',NULL,'2026-01-14 15:06:16','2026-01-15 16:00:55'),(652,15,226,'445299','Log de atualização de pedido #000009675','{\"ops\":[{\"insert\":\"Olá Equipe, Bom dia!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" O pedido \"},{\"attributes\":{\"bold\":true},\"insert\":\"000009675\"},{\"insert\":\" tem um registro de reembolso criado.\\n\\nÉ possível resgatar alguma log sobre o usuário que realizou este processo? Pelo painel admin não localizei nenhuma log sobre isso.\\n\"}]}','{\"ops\":[{\"insert\":\"Não há registros de log para a captura das informações do usuário que realizou o reembolso do pedido.\\n\"}]}','Resolvido','Baixa',NULL,'2026-01-15 17:19:12','2026-01-16 13:58:26'),(653,15,35,'445306','Inconsistência ao salvar data no preço promocional','{\"ops\":[{\"insert\":\"Bom dia, tudo certo?\\n\\nO cliente necessita cadastrar uma data final para o preço promocional e precisa que a data seja distante de forma exagerada para que ela nunca seja atendida. No exemplo abaixo, ele inseriu a data final como sendo no ano de 2099 e, ao salvar o produto, o cadastro altera para 1999.\\n\\nPoderia verificar?\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/mundoencantado/-/commit/7465dd98d6d682c6249b3a30d3e1dba8158f5406\"},\"insert\":\"Deploy\"},{\"insert\":\" realizado em produção\\n\"}]}','Resolvido','Baixa',NULL,'2026-01-16 15:02:40','2026-01-20 15:56:21');
INSERT INTO `tickets` VALUES (654,2,226,'445418','Pedidos reprovados pela Clearsale não estão alterando o status do pedido para cancelado','{\"ops\":[{\"insert\":\"Olá Equipe, Boa tarde!\\n\\nA configuração da clearsale está setada para que os pedidos cancelados se forem reprovados, porém o pedido exemplo 000009779, teve a reprovação da clearsale, mas o pedido dentro do Magento não foi cancelado.\\n\\nPor gentileza, poderiam verificar para que a configuração seja respeitada para pedidos cancelados.\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/m2/lojas/chocolandia/-/merge_requests/270\"},\"insert\":\"deploy\"},{\"insert\":\" realizado em produção.\\n\"}]}','Resolvido','Baixa',NULL,'2026-01-20 13:41:01','2026-02-11 11:24:50'),(655,5,100,'445573','Nível de acesso desconfigurado','{\"ops\":[{\"insert\":\"Prezados, o módulo Nível de Acesso para bloqueio e/ou liberaçao dos mnódulos não estão completas, por gentileza, poderiam atualizar?\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/tecnoar-compressores/-/commit/c18abc283c549c2bb563d9f091bce1545daf2cc6\"},\"insert\":\"Deploy\"},{\"insert\":\" realizado em produção\\n\\n\\tO módulo de \"},{\"attributes\":{\"bold\":true},\"insert\":\"Permissões\"},{\"insert\":\" instalado na loja, maninpula o nível de acesso \"},{\"attributes\":{\"bold\":true},\"insert\":\"Administrators\"},{\"insert\":\" a qual estava com o status \"},{\"attributes\":{\"bold\":true},\"insert\":\"Deny\"},{\"insert\":\", após alterar esse status(\"},{\"attributes\":{\"bold\":true},\"insert\":\"Allow\"},{\"insert\":\") os recursos configurados para esse nível de acesso passaram a aparecer.\\n\\n\\tTabela no banco de dados: admin_rule\\n\"}]}','Resolvido','Baixa',NULL,'2026-01-21 10:43:20','2026-02-11 11:36:25'),(656,1,147,'445686','Atualização do módulo MFA','{\"ops\":[{\"insert\":\"Bruno,\\n\\nPrecisamos que rode um deploy em produção nas lojas citadas abaixo, para ser ativado o \"},{\"attributes\":{\"bold\":true},\"insert\":\"MFA\"},{\"insert\":\" já disponibilizado pelo B2\\n\\nPoderia por gentileza realizar?\\n\\n\"},{\"attributes\":{\"link\":\"https://www.bellenzier.com.br/\"},\"insert\":\"Bellenzier\"},{\"insert\":\"\\n\"},{\"attributes\":{\"link\":\"https://www.nhsom.com.br/\"},\"insert\":\"NH Som\"},{\"insert\":\"\\n\"},{\"attributes\":{\"link\":\"https://www.velocepneus.com/\"},\"insert\":\"Veloce Pneus\"},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"insert\":\"Deploy realizado nas lojas:\\n\"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/bellenzier/-/commit/f23d499e029a7f0b6af03c7ae3ebcc4993594f4a\"},\"insert\":\"Bellenzier\"},{\"attributes\":{\"list\":\"bullet\"},\"insert\":\"\\n\"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/nh-som/-/commit/f9d47cae837a6936f531638b69dd87bfcae93563\"},\"insert\":\"NH Som\"},{\"attributes\":{\"list\":\"bullet\"},\"insert\":\"\\n\"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/velocepneus/-/commit/bc62f58bf18b77bc139a11e766346473978eb1ca\"},\"insert\":\"Veloce Pneus\"},{\"attributes\":{\"list\":\"bullet\"},\"insert\":\"\\n\"}]}','Resolvido','Alta',NULL,'2026-01-21 16:21:57','2026-01-21 16:48:44'),(657,15,248,'445685','Dúvida sobre script na loja','{\"ops\":[{\"insert\":\"Equipe, boa tarde.\\n\\nO lojista enviou o script abaixo para ser inserido na loja.\\n\\n<script>\"},{\"attributes\":{\"code-block\":\"plain\"},\"insert\":\"\\n\"},{\"insert\":\"  window.addEventListener(\'load\', function() {\"},{\"attributes\":{\"code-block\":\"plain\"},\"insert\":\"\\n\"},{\"insert\":\"    var script = document.createElement(\'script\');\"},{\"attributes\":{\"code-block\":\"plain\"},\"insert\":\"\\n\"},{\"ins