ido: \"},{\"attributes\":{\"bold\":true},\"insert\":\"100298346\"},{\"insert\":\"\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/charutos-online/-/commit/c207e8140add126e5de92e300ce9869cc34db9ed\"},\"insert\":\"Deploy\"},{\"insert\":\" realizado em produção.\\n\"}]}','Resolvido','Baixa',NULL,'2026-01-23 11:08:12','2026-01-27 16:59:06'),(659,15,232,'445794','Instalação do módulo API da Meta','{\"ops\":[{\"insert\":\"Bom dia equipe!\\n\\nPodera por gentileza instalar o módulo \"},{\"attributes\":{\"bold\":true},\"insert\":\"Amasty Mana PIXEL ID\"},{\"insert\":\" igual a loja \"},{\"attributes\":{\"bold\":true},\"insert\":\"Cama InBox\"},{\"insert\":\"?\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/m2/lojas/fixsafe/-/merge_requests/202\"},\"insert\":\"Deploy\"},{\"insert\":\" realizado em produção.\\n\"}]}','Resolvido','Baixa',NULL,'2026-01-27 17:01:39','2026-01-28 14:17:16'),(660,15,220,'445832','Redirecionamento errado ao acessar o Stock Movements','{\"ops\":[{\"insert\":\"Olá Equipe, Bom dia!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" Ao tentar consultar o stock movements de produtos, o usuário é redirecionado para a tela principal do painel.\\n\\nRedirect ocorre ao tentar mudar a paginação do relatório ou ao tentar aumentar a quantidade de registros exibidos por página.\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"SKU de exemplo:\"},{\"insert\":\" GEEKS.FLIT\\n\"}]}','{\"ops\":[{\"insert\":\"A loja em produção estva estável quando eu assumi.\\n\"}]}','Resolvido','Baixa',NULL,'2026-01-28 11:02:37','2026-01-28 14:13:51');
INSERT INTO `tickets` VALUES (661,13,249,'445578','Imagens nas vitrines não aparecem no efeito hover ','{\"ops\":[{\"insert\":\"Boa tarde time, a loja esta apresentando erro ao passar o mouse em cima das imagens:\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\\n\"},{\"insert\":{\"image\":\"data:image/png;base64,\"}},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"insert\":\"Todas as imagens dos produtos da loja estavam somente com a imagem Base cadastrada, não havia uma imagem secundária cadastrada para o produto, e por isso, o efeito hover nas vitrines e página de catálogo da loja não aparecia.\\n\\nPorém, foi necessário fazer uma validação para quando não houver uma segunda imagem cadastrada para o produto, não executar o evento mouse hover.\\n\\n\"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/m2/lojas/vivo-farma/-/merge_requests/82\"},\"insert\":\"deploy\"},{\"insert\":\" realizado em produção.\\n\"}]}','Resolvido','Baixa',NULL,'2026-01-29 11:33:22','2026-02-02 09:09:19'),(662,15,206,'445925','Venda de produto desabilitado na loja','{\"ops\":[{\"insert\":\"Olá Equipe, Boa tarde!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" O produto de \"},{\"attributes\":{\"bold\":true},\"insert\":\"SKU: 2088429\"},{\"insert\":\" está desabilitadso no painel e teve um pedido hoje, aproximadamente as 14h.\\n\\nPoderiam verificar se é possível resgatar uma log com a data da desativação deste produto?\\n\"}]}','{\"ops\":[{\"insert\":\"Aguardando o agendamento do \"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/m2/lojas/oasistabacaria/-/merge_requests/218\"},\"insert\":\"deploy\"},{\"insert\":\".\\n\"}]}','Resolvido','Baixa',NULL,'2026-01-30 15:17:47','2026-02-04 09:10:23'),(663,15,250,'446052','Imagem base do produto não aparece','{\"ops\":[{\"insert\":\"Olá Equipe, Bom dia!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" Por algum motivo a imagem base do produto não é exibida. Poderiam verificar?\\n\\nA mesma imagem é utilizada como base e hover, no hover a imagem aparece normalmente. A imagem aparece na página do produto também.\\n\\nLimpei o cache e reindexei a loja, porém, sem efeito\\n\"}]}','{\"ops\":[{\"insert\":\"No momento em que eu assumir o ticket a loja estava estável.\\n\"}]}','Resolvido','Baixa',NULL,'2026-02-03 10:38:21','2026-02-03 10:41:48'),(664,15,226,'446151','Instalação do módulo Frenet','{\"ops\":[{\"insert\":\"Boa tarde equipe!\\n\\nPoderia instalar o módulo \"},{\"attributes\":{\"bold\":true},\"insert\":\"Frenet\"},{\"insert\":\" igual a loja Way suplementos.\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/m2/lojas/chocolandia/-/merge_requests/263\"},\"insert\":\"deploy\"},{\"insert\":\" realizado em produção\\n\"}]}','Resolvido','Baixa',NULL,'2026-02-03 14:58:06','2026-02-04 09:09:38'),(665,15,180,'446158','Erro ao criar regra de Compre Junto','{\"ops\":[{\"insert\":\"Olá Equipe, Boa tarde!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" Ao tentar criar uma regra no Compre Junto, painel exibe erro. Poderiam verificar?\\n\\nSKUs utilizadas na regra.\\n\\n05669002\\n07068002\\n\\nFatal error: Call to a member function setTime() on boolean in /var/www/html/chocolatedoce/app/code/community/BIS2BIS/CompreJunto/Model/Rule.php on line 43\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/chocolate-doce/-/commit/dd6e4170edd0d1ee0767fb89a2ecbbd423d4106a\"},\"insert\":\"Deploy\"},{\"insert\":\" realizado em produção.\\n\"}]}','Resolvido','Baixa',NULL,'2026-02-04 11:02:41','2026-02-05 09:47:42'),(666,15,171,'446146','Pedido criado com o contrato de envio errado','{\"ops\":[{\"insert\":\"Olá Equipe, Bom dia!\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Descrição do Problema:\"},{\"insert\":\" O pedido \"},{\"attributes\":{\"bold\":true},\"insert\":\"100000605\"},{\"insert\":\" foi realizado com o contrato do Sedex errado e, com isso, não é possível enviar para a lista de pré-postagem.\\n\\nO contrato já foi ajustado no módulo dos Correios, porém, o pedido segue incorreto.\\n\\nPoderiam ajustar a forma de entrega deste pedido para o \"},{\"attributes\":{\"bold\":true},\"insert\":\"contrato 03220\"},{\"insert\":\" do Sedex?\\n\"}]}','{\"ops\":[{\"insert\":\"Foi necessário executar o seguinte script SQL para a correção do contrato de entrega no banco de dados da loja:\\nUPDATE `sales_flat_order`\"},{\"attributes\":{\"code-block\":\"plain\"},\"insert\":\"\\n\"},{\"insert\":\"   SET `shipping_method` = \'pedroteixeira_correios_03220\'\"},{\"attributes\":{\"code-block\":\"plain\"},\"insert\":\"\\n\"},{\"insert\":\" WHERE `increment_id` = \'100000605\';\"},{\"attributes\":{\"code-block\":\"plain\"},\"insert\":\"\\n\"},{\"insert\":\"\\n\\n\"}]}','Resolvido','Baixa',NULL,'2026-02-05 10:44:19','2026-02-05 14:35:33'),(667,2,24,'446232','Instalação do módulo de Busca','{\"ops\":[{\"insert\":\"Boa tarde Equipe! \\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Poderia por gentileza instalar o módulo:\"},{\"insert\":\" Busca\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Loja de referência:\"},{\"insert\":\" \"},{\"attributes\":{\"link\":\"https://www.astrodistribuidora.com\"},\"insert\":\"Astro Distribuidora\"},{\"insert\":\"\\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":\"Caminho do módulo no admin:\"},{\"insert\":\" \"},{\"attributes\":{\"link\":\"https://www.astrodistribuidora.com/index.php/admin/system_config/edit/section/search/key/0ed224e2567eded850e1dd5bd9b11d20/\"},\"insert\":\"Link\"},{\"insert\":\"\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/charutos-online/-/commit/c2941a62f27ea42b4305dc6a2bce4935d399c65b\"},\"insert\":\"Deploy\"},{\"insert\":\" realizado em produção\\n\\n\"}]}','Resolvido','Baixa',NULL,'2026-02-06 09:02:14','2026-02-11 09:01:11'),(668,1,1