L,'2026-02-12 15:12:15','2026-03-04 09:57:35'),(670,15,84,'446601','Erro ao acessar produto','{\"ops\":[{\"insert\":\"Olá equipe, Bom dia!\\n\\nO painel admn da loja não acessa os produtos, ao tentar o acesso, é exibida uma tela de erro report. Poderia verificar?\\n\"}]}','{\"ops\":[{\"insert\":\"O problema é oriundo de um upgrade que foi mau configurado e por isso gera uma inconsistência no banco de dados. Para resolver esse problema, foi necessário executar o seguinte código no banco de dados.\\n\\n\"},{\"attributes\":{\"background\":\"oklab(0.57742 0.0140622 -0.208604 / 0.0784314)\",\"color\":\"oklab(0.952693 0.000792831 -0.00253612)\"},\"insert\":\"UPDATE `bananabrasil`.`eav_attribute` SET `source_model`=\'pagarmev5/system_config_source_interestType\' WHERE `attribute_id`=283;\"},{\"insert\":\"\\n\"}]}','Resolvido','Média',NULL,'2026-02-18 08:25:17','2026-02-18 15:24:35'),(671,2,244,'446679','Instalação do módulo Google Analytics','{\"ops\":[{\"insert\":\"Boa tarde equipe!\\n\\nPoderia instalar o módulo GA4 por gentileza.\\n\"}]}','{\"ops\":[{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/bis2bis-stores/fullturbosparts/-/commit/2ca0a27f0014e415dbba9f065cbea8370678ea61\"},\"insert\":\"deploy\"},{\"insert\":\" feito em produção\\n\"}]}','Resolvido','Baixa',NULL,'2026-02-23 15:29:47','2026-02-23 16:21:57'),(672,15,18,'446548','Instalação do módulo Action log','{\"ops\":[{\"insert\":\"Bom dia Equipe! \\n\\nPoderiam por gentileza instalar o modulo action log na loja para que a exclusão de cadastros de clientes seja monitorada?\\n\"}]}','{\"ops\":[{\"insert\":\"Atualização do \"},{\"attributes\":{\"link\":\"https://git2bis.com.br/bis2bis/m1/modulos/dev-tools/watcher/admin/-/merge_requests/25\"},\"insert\":\"módulo\"},{\"insert\":\"\\n\"}]}','Resolvido','Baixa',NULL,'2026-02-24 13:50:09','2026-02-25 16:38:29'),(673,2,2,'446694','Requisição de pedido frete rápido','{\"ops\":[{\"insert\":\"Boa tarde Equipe! \\n\\n\"},{\"attributes\":{\"bold\":true},\"insert\":